/* Meridian Quest content pack — quests, English. Mirror every change in quests.es.js. */
/* Frederick's secret side quest (not part of the 10) */
const FQEN={npc:"fred",title:"🐾 Personal side quest: Frederick's Files",start:"a",nodes:{
 a:{say:"Frederick drops a chewed folder at your feet. Inside: vet reminders on napkins, a feeding schedule that lives in three people's heads, and 40 unposted photos of him being majestic. This dog needs an ops system.",
    codex:"Personal ops is PM discipline with smaller stakes: one source of truth, recurring reminders for anything on a cycle (food, vet, grooming), and one list everyone shares. If it repeats, it gets a reminder — memory is not a system.",
    q:"How do you organize Frederick's life?",
    ch:[{t:"One giant sticky note on the fridge",out:{r:"mid",concept:"Single source of truth",why:"It IS one source of truth — but nothing reminds anyone of anything, and the vet appointment dies the day someone needs the fridge. Half credit.",beat:"Frederick sniffs the sticky note. Unimpressed."}},
        {t:"A shared calendar with recurring reminders + one shared checklist",next:"b"},
        {t:"Hire a dog assistant",out:{r:"bad",concept:"Single source of truth",why:"An assistant for a dog's calendar is a payroll line for a problem two recurring reminders solve.",beat:"Marcus appears from nowhere. “A WHAT for the dog?”"}}]},
 b:{say:"His public awaits. Forty majestic photos, zero posts. Frederick's content pipeline?",
    codex:"Creative work batches: one session producing a month of content beats posting when you remember. AI drafts the captions; a human approves before anything goes out — Frederick cannot approve, he is a dog.",
    q:"The content plan is…",
    ch:[{t:"Post whenever you remember",out:{r:"mid",concept:"Batching & scheduling",why:"That's how it's going now — 40 photos, zero posts. Sporadic effort loses to a boring schedule every time. Half credit for honesty.",beat:"Frederick's fans refresh in vain."}},
        {t:"Monthly batch day: AI drafts captions, you approve, a scheduler posts",out:{r:"ok",concept:"Batching & scheduling",why:"One hour a month, AI does the writing, human keeps the judgment, the scheduler does the remembering. Frederick's brand: consistent.",beat:"First scheduled post hits 200 likes. Frederick remains humble."}},
        {t:"Let AI auto-post as Frederick, unsupervised",out:{r:"bad",concept:"Batching & scheduling",why:"Unsupervised auto-posting is how brands die. No review, no floor.",beat:"Within the hour, Frederick's account endorses a crypto scheme."}}]}}};
const QEN=[
 {npc:"tovar",title:"The 500-doc chatbot",late:"Corporate has rewritten the manual a few times since I brought you this. The question has not moved.",start:"a",nodes:{
  a:{say:"Store managers call me all day with policy questions. I want a chatbot on these 500 docs — and corporate rewrites them every month.",
     codex:"Two ways to give a model knowledge: train it into the model itself (slow, costly, frozen once done) — or keep it in a searchable index the model reads at answer time, fresh the moment a doc updates.",
     q:"The docs change monthly. Where does the knowledge live?",
     ch:[{t:"Train a custom model on the docs",out:{r:"bad",concept:"RAG vs fine-tuning",why:"Monthly retraining chases stale docs with money. By the time training finishes, corporate has rewritten the manual.",beat:"Priya, quietly: “That's how we lost the last lead.”"}},
         {t:"Index the docs; the bot retrieves the right pages per question",next:"b"},
         {t:"Paste all 500 docs into every prompt",out:{r:"bad",concept:"RAG vs fine-tuning",why:"You'd pay for 500 documents on every single question — and models lose focus across enormous inputs anyway.",beat:"Marcus materializes holding a calculator. Ominously."}}]},
  b:{say:"Indexing — good. One more thing: yesterday a manager asked about a policy that isn't in any document at all. What should the bot do?",
     codex:"A grounded bot answers only from retrieved text. When retrieval comes back empty, the honest moves are admitting it or routing to a human — the dangerous move is letting the model improvise.",
     q:"No matching document exists. The bot should…",
     ch:[{t:"Answer anyway from general knowledge — it usually sounds right",out:{r:"bad",concept:"Grounding & refusal",why:"“Sounds right” is how Free Churro Friday happens. An ungated answer with no source is a hallucination waiting for a customer.",beat:"Camila, from three desks away: “Don't you dare.”"}},
         {t:"Say “I don't have that policy” and route the question to the ops team",out:{r:"ok",concept:"Grounding & refusal",why:"A grounded bot that admits the gap — and hands a human the question — builds trust and shows ops which docs are missing.",beat:"The ops director nods slowly. “The bot knows what it doesn't know. Unlike my nephew.”"}},
         {t:"Make the bot apologize and end the chat",out:{r:"mid",concept:"Grounding & refusal",why:"Safe, but a dead end — no human routing means the manager's real question dies in the chat. Half credit: nothing false, nothing helpful.",beat:"Shipped with incidents. The manager calls the ops director anyway."}}]}}},
 {npc:"camila",title:"Free Churro Friday",late:"The churro thing outlived its Friday. People still bring it up, and I still don't have a fix I like.",start:"a",nodes:{
  a:{say:"The pilot bot just promised a manager ‘Free Churro Friday — all locations.’ That policy does not exist. Managers are already asking about it.",
     codex:"Models generate plausible text — when they don't know, plausible means invented. Asking nicely or lowering randomness reduces variety, not fabrication. What works: answers may only come from retrieved documents, with a citation.",
     q:"How do you kill the imaginary churros?",
     ch:[{t:"Add “don't make things up” to the instructions",out:{r:"mid",concept:"Hallucination control",why:"It helps at the margins — and fails the day it matters. Instructions nudge; they don't gate. Half credit for trying the cheap fix first.",beat:"The bot invents ‘Taco Tuesday Amnesty’ a week later."}},
         {t:"Set randomness to zero",out:{r:"bad",concept:"Hallucination control",why:"Temperature zero makes the bot confidently wrong the same way every time. Determinism isn't truth.",beat:"Camila: “Now it promises churros CONSISTENTLY.”"}},
         {t:"Ground every answer in retrieved text — no source, no answer",out:{r:"ok",concept:"Hallucination control",why:"Grounding treats the cause: the bot states only what a real document says, cites it, or admits it doesn't have the policy.",beat:"Camila drafts the official Death of Churro Friday memo. There is grief."}}]}}},
 {npc:"legal",title:"The 300-page contract",late:"The agreement got renewed since I asked you. Same three hundred pages. Same page two hundred.",start:"a",nodes:{
  a:{say:"I need Q&A over the 300-page franchise agreement. The prototype nails page 20 and faceplants on page 200.",
     codex:"Every request has a token budget — you pay for every word sent, every time — and models attend unevenly across very long inputs: the middle sags. Less, better-chosen text beats everything-and-hope.",
     q:"How do you cover all 300 pages?",
     ch:[{t:"Chunk the contract; retrieve only sections relevant to each question",out:{r:"ok",concept:"Context windows & chunking",why:"Retrieval sends the three pages that matter instead of billing legal for all 300 every time — and quality holds on page 200 like it does on page 20.",beat:"Dana closes her laptop satisfied, which legal-ly speaking is a hug."}},
         {t:"Query a one-time summary instead",out:{r:"mid",concept:"Context windows & chunking",why:"Works for “what's the gist” — fails the clause-level questions contracts exist for. Half credit: fine as a companion, wrong as the answer.",beat:"Dana: “The summary says ‘standard terms apply.’ WHICH terms, bot?”"}},
         {t:"Buy a giant context window and send all 300 pages every time",out:{r:"bad",concept:"Context windows & chunking",why:"The middle still sags, and now every parking question costs a full contract's worth of tokens.",beat:"Marcus appears. He heard the word ‘buy.’"}}]}}},
 {npc:"marcus",title:"The morning report",late:"Forty minutes a morning, times every morning since. The number got worse on its own. Sit down.",start:"a",nodes:{
  a:{say:"Someone spends 40 minutes every morning pulling sales numbers, formatting the report, emailing leadership. Can your… robot… handle it?",
     codex:"A plain model call only writes text — it can't touch a database or send email. Hand it tools (run query, send email) and it can decide which tool, in what order: that's an agent. Fixed steps live in code; judgment lives in the model.",
     q:"How does the morning report automate?",
     ch:[{t:"One giant ‘do the report’ prompt",out:{r:"bad",concept:"Agents & tool use",why:"A beautiful report full of imaginary numbers — no tools, no data access, pure fiction in a spreadsheet costume.",beat:"Leadership compliments the formatting. Then reads the numbers."}},
         {t:"An agent with tools: query → format → send",out:{r:"ok",concept:"Agents & tool use",why:"Real data through real tools, orchestrated by the model. Forty minutes becomes zero.",beat:"Marcus: “If the robot breaks, it's coming out of your budget.” He's smiling. Probably."}},
         {t:"Tell Marcus robots aren't ready",out:{r:"bad",concept:"Agents & tool use",why:"They've been ready. The CFO asking you for automation is not the person to underdeliver to.",beat:"Marcus writes something in a small notebook. You don't like the notebook."}}]}}},
 {npc:"marcus",title:"The invoice",late:"The invoice kept arriving. It has friends now.",start:"a",nodes:{
  a:{say:"This invoice. Ten thousand support tickets a month, all answered by the most expensive model money can buy. Most of them ask where their order is.",
     codex:"Models come in sizes and prices; small ones do simple work for pennies. Systems can flag their own low-confidence answers — so easy tickets go cheap, and only hard ones escalate to the flagship.",
     q:"How do you cut the bill without cutting quality?",
     ch:[{t:"Everything to the cheapest model, accept the drop",out:{r:"mid",concept:"Model routing & cost design",why:"The bill collapses — and so does quality exactly on the hard tickets that decide whether customers stay. Half credit: right instinct, no escape hatch.",beat:"Refund disputes now answered by a model that thinks a churro is a shoe."}},
         {t:"Cheap model first; escalate hard or unsure tickets to premium",out:{r:"ok",concept:"Model routing & cost design",why:"The cheap model earns its keep on “where's my order”; the flagship earns its price on the gnarly 10%. Same quality where it matters, fraction of the spend.",beat:"Marcus initials the invoice. From Marcus, that's fireworks."}},
         {t:"Ask the vendor for a discount",out:{r:"bad",concept:"Model routing & cost design",why:"A discount on the wrong architecture is still the wrong architecture, now with a longer contract.",beat:"The vendor sends a fruit basket. Marcus sends it back."}}]}}},
 {npc:"priya",title:"The 98% quote-bot",late:"Quote-bot is still 98%. Finance still has the folder. None of this got easier while we weren't looking at it.",start:"a",nodes:{
  a:{say:"Quote-bot is 98% right and auto-sends everything. Here's the other 2% — real customers, prices that lose real money. Sales loves it. Finance found the 2%.",
     codex:"Automation level should match cost-of-error: full auto where mistakes are cheap, human review where they're expensive. Confidence scores sort which is which — only the uncertain outputs wait for a person.",
     q:"Ship it, gate it, or kill it?",
     ch:[{t:"Ship — 98% is an A+",out:{r:"bad",concept:"Human-in-the-loop",why:"98% is an A+ on a quiz. On auto-sent pricing it's 200 wrong quotes a month, in dollars.",beat:"Finance starts a spreadsheet titled ‘The 2%.’ It has your name on it."}},
         {t:"Route uncertain quotes to human review",next:"b"},
         {t:"Kill it until perfect",out:{r:"bad",concept:"Human-in-the-loop",why:"Perfect never comes, and you just threw away the 98% that was printing time savings.",beat:"Sales holds a small vigil."}}]},
  b:{say:"Agreed — review queue. Now the tree question: WHICH quotes wait for a human?",
     codex:"Reviewing everything recreates the manual job you automated. Reviewing nothing is where you started. The lever is the confidence threshold — plus the cost of the error type: a too-low price hurts more than a too-slow quote.",
     q:"What goes to the review queue?",
     ch:[{t:"Every quote — humans re-check all of it",out:{r:"mid",concept:"Confidence thresholds",why:"Safe but self-defeating: you've rebuilt the 40-hour job with extra steps. Half credit — no losses, no leverage.",beat:"The reviewer now reviews quotes about reviewing."}},
         {t:"Only low-confidence quotes and any quote above a price ceiling",out:{r:"ok",concept:"Confidence thresholds",why:"Confidence catches the model's own doubt; the price ceiling catches the expensive mistakes it's confidently wrong about. Two nets, minimal drag.",beat:"Sales keeps its speed, finance keeps its sleep, Priya almost smiles."}},
         {t:"A random 10% sample",out:{r:"mid",concept:"Confidence thresholds",why:"Sampling measures error rate — it doesn't stop errors. Fine for monitoring, wrong as the only gate. Half credit.",beat:"The 2% waves at you from the un-sampled 90%."}}]}}},
 {npc:"cto",title:"Bayview's notes",late:"Bayview called back. The notes piled up in the meantime — the one thing paperwork is reliable at.",start:"a",nodes:{
  a:{say:"Our doctors drown in paperwork. I want AI summaries of visit notes — but every note is full of patient data, and I need to not end up in the news.",
     codex:"Health data is regulated. Two keys make LLM work possible: mask patient identifiers before the model sees text, and use an enterprise endpoint covered by a signed agreement (BAA) that permits health data. Consumer AI endpoints are never covered.",
     q:"How do you deliver the summaries?",
     ch:[{t:"Send raw notes to a consumer AI tool",out:{r:"bad",concept:"PII/PHI governance",why:"That's the career-ending option — a reportable breach with a timestamp.",beat:"Somewhere, a compliance officer wakes in a cold sweat, unsure why."}},
         {t:"Mask identifiers + BAA-covered endpoint + log everything",out:{r:"ok",concept:"PII/PHI governance",why:"The model sees only what it needs, on infrastructure that's allowed to see it, with an audit trail. The standard, defensible path.",beat:"Dr. Okafor: “Finally. Someone who's done this in healthcare before.”"}},
         {t:"Refuse: AI can't touch health data",out:{r:"mid",concept:"PII/PHI governance",why:"Zero risk, zero help — and someone less careful will say yes instead. Half credit for caution without craft.",beat:"The doctors keep drowning, but compliantly."}}]}}},
 {npc:"junior",title:"Theo's prompt",late:"The prompt is still sitting in a branch with my name on it. I stopped giving my mom a date.",start:"a",nodes:{
  a:{say:"I reworded the support bot's prompt and the demo got WAY better! Can we ship today? Please? I already told my mom.",
     codex:"One good demo is an anecdote. Prompt changes routinely fix one case and silently break five others. Teams keep an eval set — real past cases with known good answers — and score every change against it before shipping. Unit tests, but for AI.",
     q:"Does Theo's prompt ship today?",
     ch:[{t:"Ship it — you both saw it improve",out:{r:"bad",concept:"Evals & regression testing",why:"The demo showed one case. The eval would have shown the two refund flows it broke. Now customers get to find them.",beat:"Theo's mom is proud. The refund queue is not."}},
         {t:"Run the eval set; ship tomorrow if the score holds",out:{r:"ok",concept:"Evals & regression testing",why:"One hour of eval catches what demos hide — it finds two broken refund cases. Theo ships tomorrow, correctly, and learns the ritual.",beat:"Theo buys Priya coffee for a week. Growth arc initiated."}},
         {t:"Ask another AI which prompt is better",out:{r:"mid",concept:"Evals & regression testing",why:"AI-as-judge is a real technique — inside an eval harness with defined criteria. As a vibes oracle, it's a coin with opinions. Half credit.",beat:"The judge model says both prompts are “great!” It says that about everything."}}]}}},
 {npc:"tovar",title:"The laminated plan",late:"Theo's plan is still laminated. That is the only part of it that aged well.",start:"a",nodes:{
  a:{say:"One more thing — managers want meeting transcription inside the app. Theo has a six-month plan to build speech-to-text from scratch. He laminated it.",
     codex:"Some AI capabilities are commodities — transcription, translation, OCR — sold as excellent APIs for cents. Differentiation lives in what your product does with the output, not in rebuilding the commodity.",
     q:"Six months to build, or…?",
     ch:[{t:"Build speech-to-text from scratch",out:{r:"bad",concept:"Build vs buy",why:"Six months rebuilding what costs cents per minute, to reach quality the API already beats. Nobody will notice — except Marcus.",beat:"The lamination was the best part of the plan."}},
         {t:"Integrate a proven transcription API; build the features on top",out:{r:"ok",concept:"Build vs buy",why:"Two weeks to integrate, then the team builds what managers actually asked for — the stuff on top of the transcript. Build the last mile, buy the commodity.",beat:"Theo un-laminates the plan. Quietly."}},
         {t:"Hire human transcribers",out:{r:"bad",concept:"Build vs buy",why:"Slower, costlier, and doesn't scale past the third meeting. It's 2026.",beat:"The job posting gets three applicants. All bots."}}]}}},
 {npc:"ceo",title:"The 8-second silence",late:"I kept the recording. I still count the seconds when I play it. It is still eight.",start:"a",nodes:{
  a:{say:"Final demo. Your phone agent gives brilliant answers… eight seconds after callers stop talking. I counted. Twice. Callers hang up.",
     codex:"In real-time AI, people judge time-to-first-word, not time-to-full-answer. Two levers: stream the reply so speech starts as it generates, and open with a small fast model while heavier reasoning catches up behind it.",
     q:"Kill the eight-second silence:",
     ch:[{t:"Wait for faster hardware",out:{r:"bad",concept:"Latency engineering",why:"Latency is a design problem you can fix this sprint, not a hardware problem someone else fixes next year.",beat:"The CEO checks his watch a third time. It echoes."}},
         {t:"Stream the reply; lead with a small fast model",next:"b"},
         {t:"Add hold music",out:{r:"bad",concept:"Latency engineering",why:"Now it's eight seconds of jazz before the disappointment.",beat:"Camila vetoes the smooth-jazz license request."}}]},
  b:{say:"Priya, patching it live: “Streaming's in. Last call — what's the metric on the launch dashboard?”",
     codex:"You get what you measure. Total answer time hides the fix; time-to-first-word is what callers actually feel — with total time and answer quality tracked beside it, not instead of it.",
     q:"The headline latency metric is…",
     ch:[{t:"Average total response time",out:{r:"mid",concept:"Latency metrics",why:"Real but wrong headline — a slow-but-streaming answer FEELS instant, and this metric can't see that. Half credit; keep it secondary.",beat:"The dashboard says ‘slower.’ The callers say ‘finally.’"}},
         {t:"Time-to-first-word",out:{r:"ok",concept:"Latency metrics",why:"That's the moment the silence ends — the thing callers judge. Track total time and quality beside it, headline this.",beat:"Sub-second. The CEO puts his watch away. Priya smiles. Witnesses confirm."}},
         {t:"Number of callers who hang up",out:{r:"mid",concept:"Latency metrics",why:"A great outcome metric — but it's a lagging alarm, not a steering wheel. Half credit.",beat:"“Good news: hang-ups down. Bad news: we learned it a week late.”"}}]}}},
 {npc:"rosa",title:"The phone never stops",late:"The phone never got tired, mijo. I did, a little.",start:"a",nodes:{
  a:{say:"Mijo, the phone rings all day — orders, questions, “¿tienen birria?” I miss half the calls while I'm cooking. They tell me a robot can answer. Fine. But can it take orders WITHOUT ruining them?",
     codex:"A voice agent can take phone orders — the trick is structure. Speech gets matched into a structured order (items, sizes, extras, price) against the real menu, then read back to the caller to confirm before it counts. Free-text guessing is how you end up with three surprise birrias.",
     q:"How should the phone agent take orders?",
     ch:[{t:"Let it chat freely and write down what it hears",out:{r:"bad",concept:"Structured outputs",why:"Free text means “large horchata” becomes “¿la orchata grande?” becomes mystery tickets. No structure, no reliable kitchen ticket.",beat:"Ticket #4 reads “birria??? maybe 3?”. The kitchen weeps."}},
         {t:"Match every order to the real menu as structured items, then read it back to confirm",next:"b"},
         {t:"Keep missing calls — it's more authentic",out:{r:"bad",concept:"Structured outputs",why:"Missed calls are missed revenue — a third of Rosa's orders come by phone.",beat:"Across town, a competitor's robot says “gracias por su orden.”"}},
         {t:"Hire someone just to answer the phone",out:{r:"mid",concept:"Structured outputs",why:"A human works — at a salary, with breaks, quitting at the worst moment. A real option, a heavy cost for a solvable problem. Half credit.",beat:"The new hire quits after one Saturday rush."}}]},
  b:{say:"It works, mijo! But last night someone asked for “the wedding catering package for 200 people” — and the robot happily said YES. We do not do weddings.",
     codex:"Agents need explicit guardrails: what they may sell, ceilings on order size, and a rule that unusual requests get handed to a human. Confirmation protects the customer; guardrails protect Rosa.",
     q:"Fix the robot's enthusiasm:",
     ch:[{t:"Menu-only + a max order size + route anything unusual to Rosa's phone",out:{r:"ok",concept:"Agent guardrails",why:"Sell only what exists, up to sane limits, and escalate the weird stuff to a human. Rosa decides about weddings — not the robot.",beat:"The robot politely transfers a quinceañera inquiry. Rosa negotiates like a champion."}},
         {t:"Turn the robot off at night",out:{r:"mid",concept:"Agent guardrails",why:"That dodges the failure by dodging the revenue. Half credit — safe, but small.",beat:"The night owls order pizza instead. Traitors."}},
         {t:"Let it improvise — the customer is always right",out:{r:"bad",concept:"Agent guardrails",why:"An agent without limits will promise 200 birrias and a mariachi. The cost of error is unbounded.",beat:"Somewhere, Marcus feels a disturbance he cannot explain."}},
         {t:"Make the robot upsell everything to boost revenue",out:{r:"bad",concept:"Agent guardrails",why:"An agent optimizing revenue without limits torches trust — what it may OFFER is a guardrail decision too.",beat:"An abuelita ordering one coffee gets offered the party platter. Twice."}}]}}},
 {npc:"chuy",title:"Prep for Friday",late:"A lot of Fridays went by since I asked you. I guessed on every one of them.",start:"a",nodes:{
  a:{say:"Every Friday I guess how much barbacoa to prep. Guess low — we run out by 8pm and people cry. Guess high — Sunday me eats sad leftovers for three days. There has to be a better way, ¿no?",
     codex:"Forecasting beats gut feeling: average the last several Fridays, adjust for what's different this week (payday, weather, events), and track how wrong you were to improve each week. Overproduction is money in the trash; running out is customers in the trash.",
     q:"How much barbacoa for Friday?",
     ch:[{t:"Same as always — feel it out",out:{r:"mid",concept:"Demand forecasting",why:"The gut got Chuy this far — sometimes right, never measured, impossible to improve. Half credit for surviving on instinct.",beat:"Friday, 8:15pm: “no hay.” Hearts break audibly."}},
         {t:"Average the last 8 Fridays, adjust for payday and weather, track the error weekly",out:{r:"ok",concept:"Demand forecasting",why:"A simple forecast plus error tracking gets smarter every single week. This is data science in an apron.",beat:"Chuy tapes the forecast to the walk-in. It becomes law."}},
         {t:"Double everything and sell leftovers Saturday",out:{r:"bad",concept:"Demand forecasting",why:"Waste as a strategy — the margin dies quietly in the walk-in fridge.",beat:"A tower of Sunday barbacoa. Even Frederick, visiting, declines."}},
         {t:"Buy a big AI forecasting platform first",out:{r:"mid",concept:"Demand forecasting",why:"Tools before data discipline is backwards — the simple average with error tracking wins until the data earns a platform. Half credit.",beat:"The platform's onboarding call runs longer than Friday service."}}]}}},
 {npc:"lupe",title:"The estimate",late:"Thirty photos, and the client still wants the number today. Don Güero still says he could measure it in two hours. Neither of those has changed.",start:"a",nodes:{
  a:{say:"You're the AI person? Lupe — I do the estimates and the permits. The man up the ladder in the yellow shirt is Don Güero, he runs this site, and he sends me everything he does not want to write down. Right now that is a remodel quote for a storefront across town: thirty photos, and the client wants the number TODAY. He would drive over and measure for two hours. I do not have two hours.",
     codex:"Vision models can read measurements from photos: wall areas, fixtures, damage, materials. The reliable pattern is AI-drafted line items from the photos — quantities, materials, labor — with a human checking prices and the weird corners before it goes out. Fast AND defensible.",
     q:"How does the quote get built?",
     ch:[{t:"Eyeball the photos and quote from experience",out:{r:"mid",concept:"Vision estimates",why:"Experience is real — but unmeasured guesses win jobs that lose money. Half credit for the gray hairs.",beat:"Lupe does not argue. She just turns the folder around so you can see how many jobs are in it."}},
         {t:"AI drafts a line-item estimate from the photos; Güero verifies materials and prices before it ships",next:"b"},
         {t:"Promise to beat any other quote, figure it out later",out:{r:"bad",concept:"Vision estimates",why:"Winning on price without knowing your costs is how construction companies die with full calendars.",beat:"Lupe caps her pen. “That is how the last company on this street went down.”"}},
         {t:"Send an apprentice to measure everything by hand today",out:{r:"mid",concept:"Vision estimates",why:"Accurate — and slow. The quote lands late, and late quotes lose. Half credit for rigor without speed.",beat:"The apprentice measures beautifully. The client signed elsewhere at noon."}}]},
  b:{say:"We won it. Now the client says “while you're at it, just add one little bathroom.” ONE LITTLE BATHROOM. Don Güero already told her yes — he tells everybody yes, that is why he is not allowed to answer the phone. What do I put on paper?",
     codex:"Scope changes are where jobs bleed. The discipline is the change order: every addition gets written up with its price and schedule impact, approved BEFORE the work happens. AI drafts it in minutes from the original estimate — no awkwardness, just paper.",
     q:"The “one little bathroom” gets…",
     ch:[{t:"Just do it — keep the client happy",out:{r:"bad",concept:"Change orders",why:"Free bathrooms today, bankruptcy mañana. Unpaid scope is the quiet killer of good crews.",beat:"The crew builds it beautifully. Nobody pays for it."}},
         {t:"A written change order — price and timeline impact, AI-drafted, client-approved before work starts",out:{r:"ok",concept:"Change orders",why:"The AI turns the estimate into a change order in minutes; the client signs knowing exactly what it costs. Everyone stays friends AND solvent.",beat:"The client signs. Don Güero frames the change order like a diploma."}},
         {t:"Refuse all changes — the contract is the contract",out:{r:"mid",concept:"Change orders",why:"Protects the margin, loses the relationship — and remodels ALWAYS change. Half credit for spine, zero for flexibility.",beat:"The client calls someone else for the next job. And the next."}},
         {t:"Do it, and quietly add it to the final invoice",out:{r:"bad",concept:"Change orders",why:"Surprise charges are how trust — and occasionally court dates — get lost and found. Paper first, work second.",beat:"The final invoice starts a shouting match in two languages."}}]}}},
 {npc:"lupe",title:"Permit purgatory",late:"The permits waited. Permits are good at that. My Sundays are the ones that noticed.",start:"a",nodes:{
  a:{say:"Three projects are sitting dead because the permits aren't filed. Same forms, same city, every time — owner info, scope, drawings list, fees. I spend my Sundays copying the same data into the same boxes. There has to be dignity somewhere in this.",
     codex:"Repetitive paperwork is document automation's home turf: the project data already exists, so AI can fill the standard forms from it and track each permit's status. The human reviews before filing — a wrong permit is worse than a slow one.",
     q:"How do the permits get done?",
     ch:[{t:"Find a guy who knows a guy at the city",out:{r:"bad",concept:"Document automation",why:"The guy retires, the shortcut becomes a scandal, and the projects stay dead. Not a system.",beat:"The guy's cousin quotes a “consulting fee.” Lupe hangs up."}},
         {t:"AI fills the forms from the project data, Lupe reviews before filing, a tracker follows each permit's status",out:{r:"ok",concept:"Document automation",why:"The data exists once, the forms fill themselves, the human signs off, and nothing gets lost in purgatory again. Sundays return to Lupe.",beat:"Three permits filed by lunch. Lupe takes an actual weekend. The city is confused."}},
         {t:"Keep doing them by hand — it's tradition",out:{r:"mid",concept:"Document automation",why:"It works, slowly, and eats the estimator who should be estimating. Half credit for reliability, at the cost of Sundays.",beat:"Lupe's coffee goes cold over form B-247. Again."}},
         {t:"Outsource all permits to a consulting firm",out:{r:"mid",concept:"Document automation",why:"It works — at a fee, forever, and the capability never comes in-house. Half credit: delegated, not solved.",beat:"The consultant uses the same AI tool. Lupe watches, invoiced."}}]}}},
 {npc:"priya",title:"Say it so it's true",late:"The bot has said a lot of confident things since I flagged this. Marketing still loves the tone.",start:"a",nodes:{
  a:{say:"The support bot's answers SOUND great — confident, polished, wrong maybe one time in ten. Nobody can tell which time. Marketing loves the tone. I hate the tone. Fix the wording.",
     codex:"Trust is built with calibrated language: instructions that make the bot cite its source, mark uncertain answers as uncertain, and say 'I don't know' when nothing supports an answer. 'Be accurate' is a vibe — cite, qualify, and refuse are behaviors.",
     q:"What goes in the bot's instructions?",
     ch:[{t:"Write “be accurate and helpful” at the top",out:{r:"mid",concept:"Calibrated language",why:"A vibe, not a behavior. Models follow concrete verbs; “be accurate” measures nothing. Half credit — harmless, useless.",beat:"The bot stays confidently wrong, but now politely."}},
         {t:"Cite the source for every claim, mark uncertain answers as uncertain, and say “I don't know” when nothing supports it",next:"b"},
         {t:"Make it sound MORE confident — customers like certainty",out:{r:"bad",concept:"Calibrated language",why:"Confident wording on wrong answers is how trust dies at scale. That's polishing the failure.",beat:"Marketing applauds. Camila opens a new spreadsheet."}},
         {t:"Append a legal disclaimer to every answer",out:{r:"mid",concept:"Calibrated language",why:"Cover isn't candor — by the third message, users are trained to skip it. Half credit for lawyer instincts.",beat:"Users scroll past the disclaimer at record speed. All of them."}}]},
  b:{say:"Better. Now the live one: a caller asks “how many locations take the app?” — retrieval finds nothing current. The bot has to say SOMETHING. Word it.",
     codex:"When you can't verify, the trustworthy shape is: state what you CAN confirm, name what you can't, and hand over the path to the answer. Precision about your own limits is what accuracy sounds like.",
     q:"The bot's best reply is…",
     ch:[{t:"“Around 300 locations!” — probably close",out:{r:"bad",concept:"Verifiable claims",why:"A confident guess is a lie with good posture. One wrong number unravels every right one that came before it.",beat:"It was 41. A journalist was on the line."}},
         {t:"“I can't verify the current count. As of the last update it was 38 — here's where the live list is.”",out:{r:"ok",concept:"Verifiable claims",why:"Confirms the known, names the unknown, hands over the path. That wording IS the trust product.",beat:"Priya reads it twice. “Ship the wording.” The highest praise she knows."}},
         {t:"“I cannot answer that question.”",out:{r:"mid",concept:"Verifiable claims",why:"Honest but lazy — refusing everything unverifiable throws away the partial truth you DO have. Half credit.",beat:"The caller asks a human, who reads them the same last update."}},
         {t:"Answer normally, tuck “estimates may vary” at the end",out:{r:"mid",concept:"Verifiable claims",why:"Uncertainty in the footnote is certainty in the headline. Placement is part of wording. Half credit.",beat:"Nobody reads footnote three. Ever."}}]}}},
 {npc:"xochi",title:"The collar drop",late:"The brief is still pinned over my table. I keep adding names to it.",start:"a",nodes:{
  a:{say:"Ah, the AI person! Look — La Obra builds the barrio, I dress it. I want a collar line for the neighborhood's pets: Frederick, Canela, the whole cast. I can sketch, but these AI image tools… how do we DESIGN with them without losing the craft?",
     codex:"Image models are variation engines, not designers. The working pattern: the designer sets the brief, AI generates dozens of directions, the human curates and refines the winners — and a pick only becomes real once it's a structured spec (a tech pack): materials, measurements, colorways. Taste stays human; the machine does volume.",
     q:"How does the collar line get designed?",
     ch:[{t:"One prompt, first image, straight to production",out:{r:"bad",concept:"AI-assisted design",why:"No curation, no spec, no sizes — a first output is a mood, not a product. Production needs measurements, not vibes.",beat:"The sample arrives sized for a horse. Frederick declines to comment."}},
         {t:"AI generates variations against Xochi's brief; she curates, and the pick becomes a tech pack — materials, sizes, colorways",next:"b"},
         {t:"Copy that famous designer's collar and have AI restyle it a little",out:{r:"bad",concept:"IP & originality",why:"A restyled copy is still a copy — legally radioactive and creatively hollow. AI makes imitation faster, not legal, and the barrio deserves its own look.",beat:"Dana appears in the Studio doorway holding a cease-and-desist. Just so you know what one looks like."}},
         {t:"Hand-sketch everything like always, no AI",out:{r:"mid",concept:"AI-assisted design",why:"The craft is real and the taste is the point — but one designer exploring five directions by hand loses to the same designer curating fifty. Half credit for standards.",beat:"Week two: three beautiful sketches, ninety unexplored ideas."}}]},
  b:{say:"The tech pack came out gorgeous. Now the launch — these are virtual fits for the town's pets. How do we ship the line?",
     codex:"Curation is quality control for creative goods. Small drops with a human QA pass — does every piece fit every body it's sold for? — keep a catalog worth browsing. Auto-generating infinite listings floods the shelf with slop, and “free everything forever” just means the work can't continue.",
     q:"The drop strategy is…",
     ch:[{t:"Small curated drops; every piece checked on every pet body before listing",out:{r:"ok",concept:"Curation as QA",why:"Each drop is small enough to check and special enough to want. The eval mindset, applied to fashion: test on every body shape before it ships.",beat:"Drop one sells out by sunset. Frederick models the gold collar with unbearable dignity."}},
         {t:"Auto-generate and auto-list new items daily",out:{r:"bad",concept:"Curation as QA",why:"An infinite uncurated catalog is a landfill with a search bar. Nobody browses slop twice.",beat:"Item #4,072 is a collar with three buckles and no hole. A confused pigeon already bought it."}},
         {t:"Everything free, forever, for everyone",out:{r:"mid",concept:"Curation as QA",why:"Generous — and unsustainable. Free is a launch tactic, not a plan; the line dies when the work can't pay for itself. Half credit for heart.",beat:"Month two: Xochi quietly takes a mural commission to fund collar three."}}]}}},
 /* ---------- El Mercado Robles · the AI product manager pack (Week Two, chapter one) ----------
    Doña Chelo wants everything at once. The job is deciding what actually gets built. */
 {npc:"chelo",title:"Everything at once",late:"The list is still on the counter, mijo. I keep adding to it — that is the only part of this list that works.",start:"a",nodes:{
  a:{say:"Mijo, siéntate. I made a list. An app for orders. A robot for the phone. Something that knows when the tomatoes turn. A thing for Instagram. A machine that tells me what to buy Monday. My nephew says I need a website. Also the printer is broken.",
     doc:"lista-chelo",
     codex:"Eleven wants is not a roadmap. The first build is the one where the pain is frequent, measurable, and owned by somebody who will actually use the fix — not the one that sounds most impressive in the retelling. Everything else goes on the list and waits its turn.",
     q:"Where do you start?",
     ch:[{t:"Build the order app — it is the biggest idea on the list",out:{r:"bad",concept:"Scoping",why:"Biggest is not first. The order app touches suppliers, inventory, payments and every customer at once — six months before anyone can tell whether it helped.",beat:"Doña Chelo nods politely. Nando quietly stops making eye contact."}},
         {t:"Ask which one costs her the most hours in a normal week, and build that",next:"b"},
         {t:"Do all of them, but small — a little of each",out:{r:"bad",concept:"Scoping",why:"Eleven half-things is eleven things to maintain and nothing anyone can rely on. Half a phone bot still answers the phone wrong.",beat:"By Thursday there are eleven tabs open and nobody knows which one is real."}},
         {t:"Fix the printer",out:{r:"mid",concept:"Scoping",why:"Honestly? Unblocking the human doing the work beats a pilot nobody asked for. But the printer is not the problem she hired you for. Half credit for reading the room.",beat:"The printer works. Doña Chelo is genuinely thrilled. The list is still eleven long."}}]},
  b:{say:"The phone. It is the phone. Forty calls a day — ¿tienen masa?, ¿a qué hora cierran?, ¿tienen el queso de rancho? — and every one of them pulls Perla off the register.",
     codex:"Before you build, name what working means in a number somebody already tracks. Not “the bot is smart” — “Perla leaves the register less than five times a day.” A success metric written after launch is a story, not a measurement.",
     q:"You start building. What do you nail down first?",
     ch:[{t:"How many of the forty it has to handle before Chelo calls it worth keeping",out:{r:"ok",concept:"Definition of done",why:"That number is the whole project. It tells you what to build, when to stop, and — the part everyone skips — when to admit it did not work.",beat:"Chelo thinks. “If it takes thirty and it does not lie, I keep it.” Write that on the wall."}},
         {t:"Which model to use",out:{r:"bad",concept:"Definition of done",why:"The model is the cheapest decision here and the easiest to change later. Picking it first is choosing the hammer before you have looked at the wall.",beat:"Nando, warily: “…is that the thing my cousin has on his phone?”"}},
         {t:"The name and the logo",out:{r:"mid",concept:"Definition of done",why:"It will matter for the abuelas who have to trust it — but naming a thing before defining it is how you end up with a beautifully branded nothing. Half credit.",beat:"Perla has already drawn a logo. It is, admittedly, excellent."}}]}}},
 {npc:"chelo",title:"The abuela test",late:"Doña Meche has called every Tuesday since. She has never once thought about an app.",start:"a",nodes:{
  a:{say:"Perla says the phone thing should be an app. Mijo — my customers are señoras who answer a cell phone like it is a landline. Doña Meche calls me to ask if I have masa. She has called me every Tuesday for nine years.",
     codex:"The user you have is not the user in the pitch. A tool that needs a download, an account and a data plan gets used by people who already had all three. Meet people on the channel they already use, or accept that you built for a different neighborhood.",
     q:"How do Doña Meche's questions get answered?",
     ch:[{t:"An app — it is the cleanest experience",out:{r:"bad",concept:"Meeting the user where they are",why:"Cleanest for whom? An app is a download, a login and a tutorial standing between Meche and the word sí. She will keep calling, and now you also own an app.",beat:"Nine installs. Six are Perla testing it. One is Chava, by accident."}},
         {t:"The same phone number she already calls — the bot answers, a human takes over when it cannot",out:{r:"ok",concept:"Meeting the user where they are",why:"Zero new behavior asked of a nine-year customer. The channel stays the same; only what happens after the second ring changes. And the handoff means a miss costs a transfer, not a customer.",beat:"Meche never learns that anything changed. That is the entire point."}},
         {t:"Teach the customers to use WhatsApp",out:{r:"mid",concept:"Meeting the user where they are",why:"Some will — half the barrio is already there. But “first, change your customers” is a plan with a very long first step. Half credit.",beat:"Doña Chelo, flatly: “You teach her. I will watch.”"}},
         {t:"Put a sign on the door with the hours",out:{r:"mid",concept:"Meeting the user where they are",why:"Cheap, real, and it kills the calls from people standing at the door. Meche is not standing at the door. Half credit for trying the cheapest fix first.",beat:"The sign goes up. The phone rings. It is Meche."}}]}}},
 {npc:"nando",title:"Nando's shortcut",late:"Truck still comes. I still photograph every box. Forty minutes, every time, all this time.",start:"a",nodes:{
  a:{say:"Before you change anything — I already do this. Truck comes, I photo every box, pictures go in a folder by date, counts go in a spreadsheet on my phone. Forty minutes. It has never been wrong.",
     codex:"The workaround IS the requirements document. Somebody already solved the problem badly-but-correctly, and every quirk in their process encodes a real constraint. Replace it without reading it and the rollout dies the usual death: the tool ships, the human keeps the spreadsheet, and now there are two systems.",
     q:"What do you do with Nando's spreadsheet?",
     ch:[{t:"Replace it — the new system does all of that automatically",out:{r:"bad",concept:"Respecting the workaround",why:"You just deleted the only accurate inventory record in the building, along with forty minutes of judgment Nando applies without noticing he is applying it. He will keep the spreadsheet in secret. They always do.",beat:"Three weeks later: two inventories, disagreeing. Guess which one Chelo trusts."}},
         {t:"Sit with him through one delivery and find out where the forty minutes actually go",next:"b"},
         {t:"Leave it alone — it works",out:{r:"mid",concept:"Respecting the workaround",why:"Not wrong! It genuinely works. But forty minutes a day of a person photographing boxes is exactly the shape of thing worth improving — you just have to improve it with him, not at him. Half credit for not breaking what works.",beat:"Nando, suspicious: “That is it? You are not going to make me use an app?”"}}]},
  b:{say:"Thirty of the forty is the vendor invoices. Half are handwritten. One guy writes in Spanish, one guy writes in English with the item names wrong, and the fish guy writes PESCADO and a number.",
     codex:"Target the slowest step a machine is genuinely better at — reading messy documents — and leave the human the step that needs judgment: deciding whether the delivery is actually right. Automate the typing, not the trusting.",
     q:"So the build is…",
     ch:[{t:"Read the invoices automatically; Nando confirms the counts on screen in one pass",out:{r:"ok",concept:"Automating the step, not the job",why:"Thirty minutes becomes five, Nando still lays eyes on every delivery, and the check that catches a short shipment stays exactly where it has always been — in his head.",beat:"Nando reads it twice. “And I still say yes or no?” Yes. “Okay. Okay, that is fine.”"}},
         {t:"Full automation — invoice in, inventory updated, no human step",out:{r:"bad",concept:"Automating the step, not the job",why:"The fish guy writes PESCADO and a number. There is no version of this where nobody looks. Remove the check and the first bad delivery becomes a permanent wrong number.",beat:"The system confidently receives 400 kilos of PESCADO. It was 40."}},
         {t:"Make the vendors send proper digital invoices",out:{r:"mid",concept:"Automating the step, not the job",why:"The correct long-term fix, and completely outside your control. You cannot ship a project whose first step is “nine other businesses change how they work.” Half credit — start asking, do not wait.",beat:"Nando laughs for a full six seconds. “The fish guy. Digital invoices. The FISH guy.”"}}]}}},
 {npc:"perla",title:"The line at the register",late:"Okay so — people still ask me both things. I started keeping count. It is a lot of times.",start:"a",nodes:{
  a:{say:"Okay so — everyone asks me if we take the card for under five dollars and it is SO annoying. Can the AI do that? Also sometimes people ask what is in the mole and I have to go find Doña Chelo, but that is like twice a week.",
     codex:"The loudest request is rarely the biggest one. Reach times frequency times cost-per-miss beats whoever asked most recently and with the most feeling. And the good news: a question asked constantly with one unchanging answer is usually not an AI problem at all.",
     q:"Which one do you build?",
     ch:[{t:"The card-minimum answer — it is the most common question by far",out:{r:"mid",concept:"Prioritizing by reach",why:"Right instinct, wrong tool. One question with one unchanging answer is a sign, not a system. Building a bot for it is spending a month on a laminated card. Half credit for reading the volume correctly.",beat:"Perla stares at the sign you print. “…that is it? That is the whole thing?”"}},
         {t:"The mole question — rarer, but only Chelo can answer it and she is not always here",out:{r:"ok",concept:"Prioritizing by reach",why:"Twice a week, but each miss costs a walk, an interruption, and sometimes a sale that leaves. It is the question where the knowledge is trapped in one person's head — which is precisely what these tools are for.",beat:"Chelo, from the back, without looking up: “Finally. Somebody asks the ingredients ninety times a year and I am the only recipe.”"}},
         {t:"Both, at the same time",out:{r:"mid",concept:"Prioritizing by reach",why:"You can, and one of them takes an afternoon — but “both” is how a two-week project becomes a two-month project. Sequence them: sign today, mole this month. Half credit.",beat:"Perla writes BOTH on the whiteboard and underlines it twice. Ambition noted."}},
         {t:"Neither — register questions are not worth automating",out:{r:"bad",concept:"Prioritizing by reach",why:"There is a real one hiding in there. Dismissing the counter because the loudest request was trivial is how you miss the thing only one person in the building knows.",beat:"Perla stops bringing you problems. This is worse than it sounds."}}]}}},
 {npc:"nando",title:"The label problem",late:"It has been reading invoices this whole time. It read 12 as 112 again — in case you thought it got bored of that.",start:"a",nodes:{
  a:{say:"It is reading the invoices now. Mostly great. But last Tuesday it read 12 as 112, and Chelo ordered against a number that was not real.",
     codex:"“How accurate is it?” is the wrong question. The right one: how accurate does it need to be before it is worth using, and what happens on the misses that remain? Every system has an error budget. You either design it deliberately or discover it in production.",
     q:"What do you set before touching the model?",
     ch:[{t:"A target — what accuracy is good enough, measured on real invoices from this store",next:"b"},
         {t:"Just make it as accurate as possible",out:{r:"bad",concept:"Acceptance criteria",why:"“As accurate as possible” has no finish line, no budget, and no way to tell a good week from a bad one. It is a wish with a deadline attached.",beat:"Two weeks of tuning. Nobody can say whether it is better than Tuesday."}},
         {t:"Nothing — watch it for a month and see",out:{r:"mid",concept:"Acceptance criteria",why:"Watching real usage teaches you things a test set never will — but a month of watching with no bar to measure against just gives you a month of anecdotes. Half credit.",beat:"Nando keeps a tally on a paper towel. It is, annoyingly, the best data you have."}}]},
  b:{say:"Say we get it to 97 out of 100. That is three wrong invoices a month, and any one of them could be the tomato order.",
     doc:"eval-facturas",
     codex:"Design the failure, not just the success. The question is never whether it will be wrong — it will — but when it is wrong, who notices, how fast, and what does it cost? Good systems make their own uncertainty visible instead of hiding it behind a confident number.",
     q:"How do you handle the three?",
     ch:[{t:"Flag the low-confidence reads for Nando to check; everything else flows through",out:{r:"ok",concept:"Designing for failure",why:"The machine does the ninety-seven and raises its hand on the rest. Nando's attention goes exactly where it is worth something, and a wrong number gets caught the same day instead of at month end.",beat:"Nando's paper towel now reads: ASKED ME 4. WAS RIGHT TO ASK 4."}},
         {t:"Accept the three — 97% is great",out:{r:"bad",concept:"Designing for failure",why:"97% is great as a headline and terrible as a plan, because the three are not random. They are the messy invoices — which come from the vendor most likely to short you.",beat:"The fish guy's invoices are, statistically, all three."}},
         {t:"Have Nando double-check all of them anyway",out:{r:"mid",concept:"Designing for failure",why:"Safe — and you just rebuilt his forty minutes. If a human reads every row, the machine saved nothing but typing. Half credit: the caution is right, the target is wrong.",beat:"Nando: “So I read all of them. Like before. But now there is a screen.”"}}]}}},
 {npc:"perla",title:"Tamal season",late:"December came. December went. We ran out of hoja de maíz, and Chelo said never again, again.",start:"a",nodes:{
  a:{say:"December is coming. Every year we run out of hoja de maíz and every year Chelo says never again. Somebody told her AI can predict how much we will need.",
     codex:"A forecast is a model trained on history. If the history lives in a notebook, three people's memories and a spreadsheet that started in March, there is nothing to train on — and a confident prediction built on four data points is worse than an honest guess, because people believe it.",
     q:"Doña Chelo wants the December forecast. What do you tell her?",
     ch:[{t:"Build it — it is the highest-value thing she has asked for",out:{r:"bad",concept:"Sequencing",why:"You would be forecasting from a spreadsheet six months old and a season nobody logged. The output will look authoritative and be fiction, and she will order against it.",beat:"The model predicts a calm December. It is, of course, December."}},
         {t:"Not yet — start writing down what she buys now, and the forecast becomes real next season",out:{r:"ok",concept:"Sequencing",why:"“Not yet, and here is what makes it possible” is the most useful sentence a PM owns. It names the dependency, starts the clock on it, and refuses to sell a number nobody can stand behind.",beat:"Chelo, dryly: “So this year I guess, like always.” Yes. But this year you write down what she guesses."}},
         {t:"Use last December from the notebook",out:{r:"mid",concept:"Sequencing",why:"One year of handwritten history is real and better than nothing — as a reference, not a forecast. Say “last year we used this much” and stop talking. Half credit for using what exists.",beat:"The notebook says ¿6 cajas? 8? — with the question mark. Chelo defends the question mark."}},
         {t:"Buy a forecasting tool",out:{r:"bad",concept:"Sequencing",why:"A tool with no data has the same problem as a model with no data, except this one renews annually.",beat:"Marcus, from another timezone, senses a subscription and stirs."}}]}}},
 {npc:"chava",title:"Everything is chile",late:"Still chile, güey. The button did not move by itself.",start:"a",nodes:{
  a:{say:"Yeah, I heard. Chelo says I am breaking the data. Look — there is a line. The chile button is right here. The carne button is four screens in. You want me to make an abuela wait while I go find it?",
     codex:"Bad data almost always has a reasonable human behind it. Somebody is measured on speed, the correct action is slow, so they take the fast wrong one — reliably, every time. No model, no cleaning script and no dashboard survives a source where the wrong answer is the easy one. Fix the four screens.",
     q:"Six months of sales say this store sells almost exclusively chile. What is the move?",
     ch:[{t:"Clean it up afterward — a rule that reassigns the obvious mistakes",out:{r:"bad",concept:"Fixing the source",why:"You would be guessing what Chava meant, forever, and the guesses become the record. Meanwhile the register keeps producing the same bad rows tomorrow, at the same speed.",beat:"The rule works beautifully until somebody actually buys chile."}},
         {t:"Retrain Chava — he needs to use the right buttons",out:{r:"mid",concept:"Fixing the source",why:"He knows the right button. He is making a defensible choice under a real constraint: the line. Training against an incentive loses to the incentive every single time. Half credit — the standard is right, the lever is wrong.",beat:"Chava listens, nods, agrees completely, and rings the next one as chile."}},
         {t:"Put the six things this counter actually sells on the first screen",out:{r:"ok",concept:"Fixing the source",why:"Make the correct action the fastest one and the data fixes itself, permanently, with no rules to maintain. This is the whole job: the model was never the problem. The fourth screen was.",beat:"Chava rings carne without looking down. “Huh.” This is the highest praise available."}},
         {t:"Add a second person at the counter",out:{r:"mid",concept:"Fixing the source",why:"It does solve the line — for the price of a salary, to avoid moving a button. Sometimes headcount is the answer; here it is an expensive way to dodge a menu layout. Half credit.",beat:"Marcus, distantly, feels a payroll line appear and does not care for it."}}]}}},
 {npc:"chelo",title:"The Monday number",late:"The register does not care what month it is, mijo, and neither do I. Sit. The question kept.",start:"a",nodes:{
  a:{say:"It has been a month since we started. Your phone thing answers, what, thirty of the forty? Everything else, people tell me is going fine. People always tell me that, mijo. So tell me straight — did it work?",
     codex:"Model metrics answer “is it behaving?”. Business metrics answer “did it matter?”. They come apart constantly: a bot can answer 94% of calls correctly and save nobody a single minute, if the calls it misses are the ones that needed a person anyway. Report the second number, in her units, not yours.",
     q:"How do you answer her?",
     ch:[{t:"94% accuracy, 0.8 second response, 31 of 40 calls handled",out:{r:"mid",concept:"Business metric vs model metric",why:"All true, all real, and none of it answers the question she asked. She runs a store; accuracy is not a thing she can bank or spend. Half credit for measuring anything at all.",beat:"Chelo looks at the numbers for a long moment. “And?”"}},
         {t:"Perla left the register five times a day. Now it is once. That is about nine hours a week back on the floor.",next:"b"},
         {t:"It is working great",out:{r:"bad",concept:"Business metric vs model metric",why:"A month of work and the report is a vibe. If you cannot say what changed in her terms, you either did not measure it or you would rather not say.",beat:"Thirty years of vendors have told Doña Chelo it is working great. She has a face for it. You are seeing the face."}}]},
  b:{say:"Nine hours. Okay. Now the other one — the thing that reads the tomato invoices. Be honest with me.",
     codex:"The hardest deliverable is the one that says stop. A pilot that did not pay off is information, and killing it cheaply is a win you should be able to say out loud. The alternative is a graveyard of half-live projects quietly billing somebody forever.",
     q:"The invoice reader saves Nando twenty minutes a week and costs you an hour a week to maintain. What goes in the report?",
     ch:[{t:"That it costs more than it saves, and the recommendation is to turn it off",out:{r:"ok",concept:"Honest review",why:"Naming your own project as the one to kill is what makes every other number you report believable. And it is not a failure — you now know exactly which part was worth keeping.",beat:"Chelo is quiet. Then: “You just told me to stop paying you for something.” She writes your name on the wall by the register — under a name in older handwriting."}},
         {t:"Leave it running — it is already built and it is not hurting anything",out:{r:"bad",concept:"Honest review",why:"It costs an hour a week forever, it will drift, and one day it will be wrong while nobody is watching. “Already built” is the most expensive reason to keep anything.",beat:"Eleven months later the fish guy changes his handwriting. Nobody notices for six weeks."}},
         {t:"Report the twenty minutes saved and leave the maintenance cost out",out:{r:"bad",concept:"Honest review",why:"That is not a report, it is a sales pitch with a spreadsheet on it. The first time she finds the missing hour, every number you ever gave her is worth nothing.",beat:"Nando knows. Nando always knows."}},
         {t:"Hand it to Nando to maintain himself",out:{r:"mid",concept:"Honest review",why:"Sometimes exactly right — the person closest to the work should own the tool. But handing an hour a week of upkeep to somebody who did not ask for it is a cost transfer dressed as a handoff. Half credit: ask him first.",beat:"Nando, evenly: “Is this the part where it becomes my problem?”"}}]}}},
 /* ---- Taller Herrera (24-31) ---- */
 {npc:"tacho",title:"The door",late:"The door still goes up at seven, joven. I still don't need a computer guy. Come look anyway.",start:"a",nodes:{
  a:{say:"Three cars on the lifts. A fourth on the sidewalk, because the paper isn't ready. Chelo says you're a computer guy. I told her I don't need a computer guy. She said, and I'm quoting, “I didn't say the computer guy was for you. Yesenia's book is full.” Then she hung up on me. So. What are you, exactly, joven?",
     codex:"The loudest person in the room is rarely the bottleneck. A shop is a line — car in, diagnosis, parts, paper, car out — and somewhere on that line one step is waiting on everything else. Walk the line and find the step that waits before you say the word “app.” Pitch to the constraint, not to the objection; the objection is just where the noise is.",
     q:"Tacho is waiting. What do you say?",
     ch:[{t:"Pitch the intake app — photo in, estimate out, no more paper",out:{r:"bad",concept:"Finding the constraint",why:"You answered a question nobody asked. The lifts are full; the hands are not the problem. The fourth car is waiting on paper, and you just offered to sell the mechanic a faster way to do the one thing he isn't doing.",beat:"Tacho goes back under the Caprice mid-sentence. Your sentence, not his."}},
         {t:"“Show me how a car gets from the street to a lift.”",next:"b"},
         {t:"“Chelo sent me. Trust me.”",out:{r:"mid",concept:"Finding the constraint",why:"A referral opens a door. It doesn't say where the work is. Chelo vouched for your judgment, not for a plan, and the man in front of you hasn't seen either yet. Half credit — the name got you in; it won't get you a lift.",beat:"“Chelo also sent me a guy who sells ice. It's a shop, joven, not a church.”"}},
         {t:"Offer to fix the tablet — you heard they have one that doesn't get used",out:{r:"bad",concept:"Finding the constraint",why:"The tablet isn't broken; it's unused, which is a different problem with a different owner. Fixing a thing that works puts the fight back on the man who put it in the drawer, and you just picked a side in a fight you haven't even heard about yet.",beat:"Moy, from bay two, not looking up: “It works, profe. That's the problem.”"}}]},
  b:{say:"Compa, I read job postings for my nephew, so I know what you are — you're the one who figures out what the machine should do and what it shouldn't. Fine. This is the book. Date in. What they said it was. What Tacho said it was. Parts ordered, parts here, done, called, paid. One line per car. If I'm sick, the shop doesn't know what's on the lifts.",
     codex:"A schedule that lives in one person's handwriting is a workaround, with one difference from most: when that person is out, the building goes blind. That makes it urgent, not disposable. Every column exists because something once went wrong without it. Read the book with the person who keeps it before you build the thing that replaces it, or you'll rebuild it, minus the lesson.",
     q:"What do you do with the book?",
     ch:[{t:"Digitize the book this week — same columns, on a screen",out:{r:"bad",concept:"Reading the workaround",why:"You'd copy her columns without knowing why each one exists, and the first one you drop is the one that saved a car once. A screen with her columns is her book with a login — the single point of failure kept, the lesson lost.",beat:"The first digital version has no column for “what they SAID it was.” Tacho asks where it went."}},
         {t:"Read a week of it with her and write down what each column is for",out:{r:"ok",concept:"Reading the workaround",why:"Now the book is a requirements document instead of a mystery, and Yesenia is the author instead of the obstacle. You learn which columns are the schedule, which are the memory, and which one is the paper that follows the car — before a single screen exists.",beat:"“That column? That's the repair order — the RO, every shop calls it. The one paper that follows the car. Nobody's ever asked me what the columns mean, compa. Nobody.”"}},
         {t:"Hire a second service writer so it isn't all on her",out:{r:"mid",concept:"Reading the workaround",why:"It does take the weight off one person — for the price of a salary, and now the schedule lives in two heads that have to agree. You made the bottleneck two people wide instead of removing it. Half credit for noticing she's carrying it alone.",beat:"Yesenia: “Fine. Then I train the new one. From the book. Which she also can't read.”"}}]}}},
 {npc:"moy",title:"The photo estimate",late:"Profe, the bumper photo's still on my phone. So's the number I shouldn't have texted.",start:"a",nodes:{
  a:{say:"Profe, don't tell Tacho yet. A customer texted a photo of a crumpled rear bumper. I ran it through my phone, it spit out line items and a total, and I texted back “around $1,200.” It said 92% confidence, so that's basically a quote, right? I just wanted to be the one who answered for once. She's coming in at four.",
     codex:"An estimate looks like a prediction and works like a promise: the customer hears a number and plans around it. A tool can draft the line items from a photo in seconds, and that draft is worth having. But the number that leaves the building is a commitment, and a commitment needs the person who will stand behind it to look first. Automate the draft. Never automate the promise.",
     q:"The $1,200 is already out there. What's the rule from here?",
     ch:[{t:"Let the $1,200 stand — the tool is usually close",out:{r:"bad",concept:"Draft vs commitment",why:"The phone can't see the bracket behind the bumper, and neither can Moy from a text. When the real number is $1,900 the customer doesn't remember “around” — she remembers $1,200, and the shop eats the difference or the trust. Usually close is not a price.",beat:"The customer arrives with a screenshot. Tacho reads it and says nothing, which is louder."}},
         {t:"The phone drafts the line items; Tacho looks at the car before any number leaves the shop",out:{r:"ok",concept:"Draft vs commitment",why:"The draft does the typing and Moy still gets to be fast — he just isn't the one who promises. Tacho's eyes on the bracket cost four minutes and turn a guess into a number the shop can stand behind. The tool speeds up the estimate; it never becomes the estimate.",beat:"Tacho: “The guide says three point two hours for that bumper. That's book time. The paper says what I saw. Now you know why I don't text numbers, joven.”"}},
         {t:"Ban phone estimates entirely — nobody texts a number, ever",out:{r:"mid",concept:"Draft vs commitment",why:"Safe, and it costs you the customer who needed a ballpark by five and got one from somebody else. The problem was never that a number went out; it's that a number went out unread. Half credit — the instinct to protect the promise is the right one.",beat:"By five the same customer has DM'd Frederick the bumper photo, asking for a price. He has not replied. He is napping."}},
         {t:"Send the phone's line items with “estimate, not a quote” in the footer",out:{r:"mid",concept:"Draft vs commitment",why:"Uncertainty in the footer is certainty in the headline — the customer reads $1,200 in big type and the disclaimer in small. Say it so it's true: if the number can move, the number is what has to say so. Half credit for knowing it wasn't a quote.",beat:"She reads the total. She does not read the footer. Nobody has ever read the footer."}}]}}},
 {npc:"moy",title:"The parts run",late:"I still walk to Calle Dos for parts. My legs have opinions now.",start:"a",nodes:{
  a:{say:"Profe, walk with me, it's faster than explaining. Calle Dos, twice a day, because the shop finds out it's out of something when Tacho's hand is already in the engine. Last month a supplier shipped the wrong alternator and we paid the deposit on it twice. What if the system just orders? Stock gets low, it orders, done. I could set it up tonight.",
     codex:"Split every process into the steps that can be undone and the ones that can't. Typing, counting, watching a shelf, drafting an order — all reversible, all boring, all fair game for full automation. Money leaving the building is not reversible, and a system that reorders cannot tell wrong from low. Automate right up to the irreversible step, then put a person's finger on the button.",
     q:"Moy wants ordering automated. How far does it go?",
     ch:[{t:"All the way — stock hits the reorder point, the system orders",out:{r:"bad",concept:"The irreversible step",why:"A reorder point knows one thing: the count is low. It doesn't know the count is low because the last shipment was wrong, or because a car left with the part still on the invoice. The system that orders can't tell wrong from low, and every mistake now ships with a deposit attached.",beat:"Three alternators arrive. All wrong. All with a core charge."}},
         {t:"The system watches stock and drafts the order; a person hits send",next:"b"},
         {t:"Keep walking to Calle Dos — it works",out:{r:"mid",concept:"The irreversible step",why:"It does work. It also costs a mechanic-in-training two hours a day of legs, and the shop still finds out it's short when the hand is already in the engine. Not every workaround deserves to be kept. Half credit for refusing to automate what you haven't understood.",beat:"Moy nods. Moy keeps walking. Somewhere around the panadería his legs start forming opinions."}}]},
  b:{say:"Okay but Yesenia's not going to approve every bottle of wiper fluid, profe. She said so with her whole face. And look — there's a page in the parts binder, older handwriting, somebody's plan: stock low, system orders, nobody on send. Tacho left it in there. I think as a warning. So if a person hits send — on what? Brake pads, sure. Zip ties? Where's the line?",
     codex:"The line between “flows” and “waits for a person” isn't drawn by price alone; it's drawn by what can't be taken back. A part you can return is a small mistake. A deposit you pay twice, a part number nobody has ordered before, an order above the ceiling — those are the ones that hurt. Name them, gate them, and let everything else move on its own.",
     q:"Where do you draw the line?",
     ch:[{t:"Everything waits for Yesenia — she approves every order",out:{r:"mid",concept:"Drawing the line",why:"Nothing wrong ships, and nothing ships until Yesenia has a free minute, which she doesn't. You built the bottleneck a screen. The point of a gate is that most things don't have to stop at it. Half credit for putting a person on send.",beat:"Day three: forty-one orders waiting. One is wiper fluid. Yesenia has not looked at it, on principle."}},
         {t:"Consumables flow; anything over the ceiling, with a deposit, or a new part number waits",out:{r:"ok",concept:"Drawing the line",why:"Two hundred things on the shelf and maybe fifteen can hurt you. Rags and fluid flow on their own; a deposit, a ceiling and a part number nobody has ordered before stop for a person. Yesenia approves what matters, sees nothing else, and the mistake that cost double can't happen twice.",beat:"Moy: “The old part's a deposit. Send the wrong one back and you pay it twice. That's the core charge.” He writes CORE on his hand in marker."}},
         {t:"Moy approves from his phone between lifts — he's fastest",out:{r:"bad",concept:"Drawing the line",why:"The fast wrong action, built in on purpose. A person on send only counts if that person is looking; an approval tapped under a car with one greasy thumb is the full-auto plan wearing a name tag. You kept the gate and removed the guard.",beat:"He approves an order from under a car. It's for a car that left yesterday."}},
         {t:"Ask the supplier to stop sending wrong parts",out:{r:"mid",concept:"Drawing the line",why:"Correct, and entirely outside your control — Nando's fish guy, in a different apron. A supplier can be asked; the shop still needs a plan for the day the ask doesn't hold. Half credit: make the call, then build the gate as if you hadn't.",beat:"The supplier says of course. The next box is the right alternator, for the wrong year."}}]}}},
 {npc:"yesenia",title:"The tablet, again",late:"The tablet's in the drawer, compa. Same drawer. It's very well rested.",start:"a",nodes:{
  a:{say:"Compa, the tablet. Bought last year for the paperwork, so Tacho could put in what he did while he's doing it. It lives in a drawer. He will not touch it. So he tells me, and I retype it, and if I'm on the phone he tells Moy, and Moy tells me, and I retype that. Everyone's tried. His cousin tried. The guy who sold it tried. Your turn.",
     codex:"When one person refuses a tool, the reflex is to work on the person: train them, explain again, buy a nicer version. But a refusal from someone who has decided is not a training gap. The lever is the workflow — who touches what, and when. Move the step to someone who will do it, keep the decision with the person who owns it, and nobody has to be converted.",
     q:"Everyone has tried. What do you try?",
     ch:[{t:"Train Tacho again — slowly, patiently, one screen at a time",out:{r:"bad",concept:"Workflow over person",why:"He isn't confused; he's decided. Training a decision is a conversation he's already had with everyone who sold, bought or loved that tablet, and losing it again costs you the one thing you had walking in — that you hadn't asked him to change.",beat:"He sits through the whole training. Then he wipes his hands on it."}},
         {t:"Change who touches what — Moy narrates at the lift, Yesenia confirms, Tacho signs as always",next:"b"},
         {t:"Buy a bigger tablet — bigger buttons, bigger type",out:{r:"mid",concept:"Workflow over person",why:"A real fix for a man whose objection is buttons. His isn't. His objection is what goes on the paper and who has to stand behind it, and no screen size answers that. Half credit for trying the cheap thing before the hard one.",beat:"The bigger tablet goes in the same drawer. It does not fit. It goes in anyway."}},
         {t:"Hire someone to type for him",out:{r:"mid",concept:"Workflow over person",why:"A salary to route around a signature. It works the way a second service writer works — the retyping still happens, it just happens to someone new, and what he did still passes through a mouth before it hits a screen. Half credit for seeing the retyping is the cost.",beat:"Yesenia: “So we'd pay somebody to do what I do. Compa, I'm right here doing it.”"}}]},
  b:{say:"Okay. So Moy talks at the lift, the phone writes it, I check it. I like it. But here's the thing, compa — at the end, Tacho signs the paper. Every job. He reads it, he signs it, the customer gets it. That's the one part nobody has ever gotten him to skip, and honestly I don't want him to. So what happens to the paper?",
     codex:"Data is cheapest where it's born — at the lift, in the words of the person doing the work, while they're doing it. A signature is different: it's the moment someone with authority reads the job before the customer does. Capture the data where it's born and keep the signature exactly where it lives. The paper can change shape. The step where somebody reads it should not.",
     q:"Tacho signs the paper. Does the paper change?",
     ch:[{t:"The paper becomes a printout of what Moy narrated; Tacho signs that",out:{r:"ok",concept:"Where the signature lives",why:"Nothing was taken from him and nothing was asked of him. He still reads every job before the customer does, still holds the pen, and now the words on the page were spoken at the lift instead of retyped twice. He never comes around. That's the win.",beat:"Tacho reads it, corrects one word, signs. “Fine.” Yesenia: “That's the write-up. It used to be me. Twice.”"}},
         {t:"Skip the signature — the narration's enough",out:{r:"bad",concept:"Where the signature lives",why:"You removed the only step where the master mechanic reads the job before the customer does. The narration is what Moy saw; the signature is what Tacho knows. Without it the write-up is a rumor with a shop logo on it.",beat:"A write-up goes out saying “replaced alternator.” It was the belt."}},
         {t:"He signs on the tablet with a stylus",out:{r:"mid",concept:"Where the signature lives",why:"You moved the fight one inch. The signature is the same; the surface is the thing he already refused, and now it's in his hand with a pen attached. The workflow was right up to the last step, then it reached for the drawer. Half credit.",beat:"The stylus is in the drawer by lunch. The tablet, understandably, is there to meet it."}}]}}},
 {npc:"tacho",title:"The sound",late:"Cars still make noises. Phones still have opinions about them. Pop the hood.",start:"a",nodes:{
  a:{say:"Corolla. The survey crew's, the ones laying out the trolley. Comes in with a noise. Moy plugs his phone into the port: “wheel bearing, left front.” Ninety-one percent, it says. I put the hood up and listen four seconds. Belt tensioner. Nobody's yelling, joven. He's not wrong to look. I'm not wrong to listen. But one of us signs the paper, and the car goes on a freeway.",
     codex:"The honest version of “what stays human” isn't “the machine can't.” It's about cost: when a wrong answer is a car on a freeway, the bar for trusting a number is a different bar than for a text message. Let the tool read and suggest, let the person whose name goes on the paper decide, and write both down — so the gap becomes a lesson instead of a habit.",
     q:"The phone says bearing. Tacho says tensioner. What's the rule in this shop?",
     ch:[{t:"Trust the code — the phone has the data, the ear has a hunch",out:{r:"bad",concept:"The confidence bar",why:"A code says where the computer noticed something, not what's wrong. A bearing and a tensioner can throw the same complaint at a sensor and sound nothing alike to a person who has heard a thousand of each. You put a guess with a percentage on it above thirty years of ears.",beat:"The Corolla comes back on a tow truck. Tacho says nothing. Moy hears it anyway."}},
         {t:"The phone reads codes and suggests; Tacho's ear decides; Moy writes down both, every time",out:{r:"ok",concept:"The confidence bar",why:"The phone stays, because it's useful and because banning it teaches Moy nothing. The decision stays with the ear that carries the consequence. The notebook is the real build: every disagreement written down, and in a year Moy knows where the phone is wrong — the one thing no phone can tell him.",beat:"Tacho: “A car that comes back is a comeback. That's the number I run this shop on. Write both down, Moy. In a year you'll hear it too.” Quieter, to you: “I'm not scared it's wrong, joven. I'm scared it's right enough he stops listening.”"}},
         {t:"Take the phone away from Moy — no diagnosing by app in this shop",out:{r:"mid",concept:"The confidence bar",why:"You just banned the tool from the only person who'll be here in ten years. The tools are already inside the building; they came in a pocket. Banning them doesn't make Moy listen, it makes him diagnose in the parking lot. Half credit for protecting the ear — wrong lever.",beat:"Moy puts the phone away. Moy checks the code in the alley. Tuerca watches from the Caprice; she doesn't tell."}},
         {t:"The phone drives; Tacho double-checks every car anyway",out:{r:"mid",concept:"The confidence bar",why:"That's Tacho doing every diagnosis with an extra step in front of it. If the master mechanic re-listens to every car, the phone saved nothing and Moy learned nothing — the phone said, Tacho corrected, nobody wrote it down. Half credit: the check is right, the order is backwards.",beat:"Tacho listens to every car twice now. Once for the noise, once to find out what the phone thought it was."}}]}}},
 {npc:"yesenia",title:"The one it shouldn't have answered",late:"It answered another warranty question while you were gone. Politely. Wrong, but politely.",start:"a",nodes:{
  a:{say:"Compa, the intake thing — the one that takes “what's wrong with your car” and books a slot — it's good, I like it, forty calls a day and I'm on maybe ten. But. Yesterday a lady asked it “is this covered under my warranty?” and it said “Yes, most likely.” It isn't. Not even a little. She's already told her sister. Her sister has already told me.",
     doc:"incidente-garantia",
     codex:"Scope is a list, not a mood. A tool that's been told to “be helpful” will help with anything, including the questions it has no business answering. Write down the three things it may do, and route everything else to a person — with the customer's question attached, so nothing is lost in the handoff. “That one's for a human” isn't the assistant failing. It's the assistant working.",
     q:"What do you change about the intake assistant?",
     ch:[{t:"Add “don't answer warranty questions” to its instructions",out:{r:"mid",concept:"Scope as a list",why:"Instructions nudge; they don't gate. Tell it not to answer warranty questions and it'll do fine until someone asks about “the coverage thing,” and then you're back to Free Churro Friday with a grease stain. A rule written as a mood holds until the wording changes. Half credit — right target, soft fence.",beat:"Next week: “Is the repair guaranteed?” “Yes, most likely.” It did not say warranty. It was very careful not to."}},
         {t:"A short list of what it may do; everything else goes to Yesenia with the question attached",out:{r:"ok",concept:"Scope as a list",why:"Describe the problem, book a slot, say how long a job takes — three things, written down. Everything else doesn't get a guess, it gets a person, and the person gets the exact question so the customer never says it twice. The assistant hands off forty times a week now. Each one is it working.",beat:"The next warranty question gets “That one's for Yesenia — she'll call you before noon.” Yesenia: “It's polite. It's more polite than me.”"}},
         {t:"Turn it off — one wrong answer is one too many",out:{r:"bad",concept:"Scope as a list",why:"The fix for one wrong answer is a boundary, not an off switch. You gave forty calls a day back to a counter that had them, to punish a tool for doing the one thing nobody told it not to do. Nothing was learned and the phone is ringing.",beat:"The phone rings on the counter. It's a warranty question."}},
         {t:"Let it answer, but add “check your paperwork” to the end",out:{r:"mid",concept:"Scope as a list",why:"Cover isn't candor. “Yes, most likely, check your paperwork” is still a yes with a hedge stapled on, and the customer hears the yes. A disclaimer protects the shop from the sentence; it doesn't protect the customer from believing it. Half credit for knowing it shouldn't sound sure.",beat:"The lady's sister calls. She has checked her paperwork. She would like to discuss “most likely.”"}}]}}},
 {npc:"tacho",title:"The cousin's platform",late:"My cousin still calls on Sundays. The price went up. Everything he does goes up.",start:"a",nodes:{
  a:{say:"Walk with me, joven, Chelo owes me a coffee. My cousin Rigo sells software for shops — intake, estimates, parts, the texting, a dashboard, whatever that is. Four hundred a month. “Everything you built, but professional.” He said it wearing a tie. Yesenia did the arithmetic: yours costs us two hours a month to keep. His has a scheduling board. She saw it and went quiet, and she doesn't go quiet. ¿Cómo la ves?",
     codex:"Build, buy, or don't — three answers, and “it does everything” is not an argument for any of them. Buy when the piece you'd buy beats what you have, at a price lower than what keeping yours costs. A platform is a bundle of decisions wearing one price tag: take it apart, buy the piece that wins, keep what works, say no to the rest, and write the number down.",
     q:"Four hundred a month, everything included. What do you tell him Sunday?",
     ch:[{t:"Buy it — it does everything",out:{r:"bad",concept:"Build, buy, or don't",why:"Everything is the price. The shop would use three of forty features and pay for forty, every month, forever, and the three it used were the three you'd already built. “Does everything” is what a product says when it hasn't asked what you do.",beat:"Chelo, from behind the produce, not looking up: “Forever is the expensive word.”"}},
         {t:"Buy only the scheduling board — keep what works, say no to the rest of the bundle",out:{r:"ok",concept:"Build, buy, or don't",why:"The board fills a gap you never built for, and Yesenia has wanted it for four years. The parts draft and the texting cost two hours a month and work; his versions replace them with nothing better. One line item bought, one number written down, and a no to the other thirty-nine, to his face.",beat:"Tacho, walking back: “You told my cousin no to my face.” It isn't a complaint."}},
         {t:"Never buy anything — you build what you need",out:{r:"mid",concept:"Build, buy, or don't",why:"A real answer for a three-bay shop, said too early. Some things are worth buying — a scheduling board somebody else maintains beats one you patch at midnight. “Never” isn't a comparison; it's a mood with a budget. Half credit for not being dazzled.",beat:"Tacho: “Never is my word, joven. You don't get to use it yet.”"}},
         {t:"Buy it — he's family, and family is how this street works",out:{r:"bad",concept:"Build, buy, or don't",why:"Family is a reason for dinner, not for software. A cousin's price is still a price, a cousin's migration still breaks the book, and the cousin will still be at Christmas when it doesn't work. You just made the shop's monthly bill a family matter.",beat:"Sunday. Rigo's demo crashes on the word “Caprice.”"}}]}}},
 {npc:"yesenia",title:"The book",late:"The book's on the counter, compa. I never decided what to do with it. I'm asking you.",start:"a",nodes:{
  a:{say:"Six o'clock. The book's on the counter. The intake thing books the slots, Moy narrates, Tacho signs, the parts wait for me only when they should. I haven't opened this since Tuesday. So what do I do with it? Four years, compa. I'd like to go home at six once and see what it looks like.",
     codex:"The last thing you hand over isn't a tool; it's the map of how the work flows now — who touches what, who signs, which step can't be undone. That map is what lets the shop own the process instead of renting it from you. And the old record doesn't get thrown out. It's a year of exceptions nobody typed. It gets closed, and kept where it can be read.",
     q:"What do you do with the book?",
     ch:[{t:"Throw it away — the system has all of it",out:{r:"bad",concept:"Owning the process",why:"The system has the columns. The book has the exceptions — the car that came in twice, the part that was right on paper and wrong in the box, the note in the margin nobody typed because there was nowhere to type it. A year of that goes in the bin with the cover.",beat:"Tacho lifts it out of the bin without a word and puts it back on the counter."}},
         {t:"Close it. Shelve it next to Tacho's manuals. The map goes on the wall.",next:"b"},
         {t:"Keep it running in parallel — forever, just in case",out:{r:"mid",concept:"Owning the process",why:"That's Nando's secret spreadsheet with a name on it. Two records, one of them by hand, kept by the one person who was supposed to stop being the record. “Just in case” is how a workaround outlives the thing that fixed it. Half credit for respecting what's in it.",beat:"Yesenia: “So I keep it. At six. After.” She doesn't say the rest."}}]},
  b:{say:"Okay. Shelf, next to the manuals — he'll like that more than he'll say. Now the wall. Moy already taped his own rule over bay two: “Phone suggests. Tacho decides. Write both.” In marker. So what goes next to it? I can write the whole thing up, every screen, every button. Or one page. Or nothing, it's all in the system anyway. Tell me before I start typing, compa, because I will.",
     codex:"A process map is one page. The steps in order, the person at each one, the ones that need a signature, and the steps that can't be taken back — circled. It hangs where the next person can read it from the door without logging in. Forty pages is a manual nobody opens; nothing is the old book with a login. One page is what a shop can own.",
     q:"What goes on the wall?",
     ch:[{t:"The full manual — forty pages, every screen, every button",out:{r:"mid",concept:"The one-page map",why:"Nobody reads forty pages in a shop; they ask Yesenia, which puts her back where she started. Everything in it is true and none of it is findable with grease on your hands. Half credit — it's honest work, and it belongs in a drawer under the one page.",beat:"Forty pages, tabbed and laminated. Moy asks Yesenia where the parts step is. She tells him. Page nineteen."}},
         {t:"One page — how a car moves, who touches what, the irreversible steps circled",out:{r:"ok",concept:"The one-page map",why:"This is the process map, and it's the real deliverable: the shop can run it, read it from the door, and hand it to the next person without calling you. Tacho's signature is on it as a step; the parts gate is a circle. The work is theirs now. That's what you were for.",beat:"Yesenia tapes it by the counter and writes under it, “If you're reading this, I'm at lunch.” The shop shirts arrive that day: Tuerca on the pocket, Yesenia's idea."}},
         {t:"Nothing on the wall — it's all in the system",out:{r:"bad",concept:"The one-page map",why:"A system nobody can read from the door is the book, digitized — one place the process lives, and a login between it and everyone. The day the screen is dark, the process is whatever Yesenia remembers. You built the single point of failure back with better fonts.",beat:"The internet goes out on a Tuesday. Everyone looks at Yesenia."}}]}}},
 /* ---- Panadería La Espiga (32-39) ---- */
 {npc:"licha",title:"The thirty conchas",late:"The conchas kept coming out of the oven while you were away. So did the trash.",start:"a",nodes:{
  a:{say:"Don Tacho says you don't sell anything. Good. I don't need anything sold. I asked him what you were for, then, and he said to ask you what I throw away. So look. Tuesday: thirty conchas in the trash. Wednesday: sold out by nine, señoras leaving with nothing. Same dough, same oven, same hands. I want a machine that tells me the number, and I want it before four tomorrow.",
     codex:"Before you forecast, find where the number is born. A forecast is only as good as the count it eats — what was made, what sold, what was thrown out, and when. Most shops record one of those and guess the rest. Trace the number back to the hand that writes it before you promise that a machine can predict it.",
     q:"Where does the number come from?",
     ch:[{t:"Build the forecast from the register — it already knows what sold",out:{r:"bad",concept:"Tracing the number",why:"The register knows what sold. It does not know what was baked, what was thrown out, or what time the tray went empty — which is the whole question. A model trained on sales alone learns that the bakery never runs out, because an empty shelf sells exactly zero.",beat:"The model recommends baking exactly what sold out. Forever. Wednesday's line gets longer."}},
         {t:"Find out who counts what, and when, before promising a number",next:"b"},
         {t:"Bake the average of the two days",out:{r:"mid",concept:"Tracing the number",why:"That is the gut's honest version, and it is what she does now. But the average of thirty too many and thirty too few is a number with no reason inside it. Nobody measured why the two days were different. Half credit for refusing to overbake on a hunch.",beat:"Thursday: fifteen in the trash. Friday: out by ten. Licha calls it progress. Bolillo, from the flour bin, does not."}},
         {t:"Buy a bakery app with forecasting built in",out:{r:"bad",concept:"Tracing the number",why:"A tool with no history has the same problem as a model with no history, except this one renews annually. The app needs the count to exist before it can learn from it, and nobody in this building has been asked for the count.",beat:"The app asks for two years of data. Licha looks at the paper strip on the board."}}]},
  b:{say:"Sol's strip. Every night she writes what is left of each thing and pins it to the board — I did not ask her to; she started on her own. Tito reads it at 3:45, some nights. Nobody writes what time anything ran out. When it is gone, it is gone, and the señora goes somewhere else. So there is your count. It is on a piece of paper nobody asked for.",
     codex:"The data you need is usually already being collected by the person nobody asked. A strip on a corkboard, a tally on a napkin, a column in somebody's head. Before you add a system, add the missing column to the record that already exists, and keep the person who keeps it. A new tool replaces the habit; a new column extends it.",
     q:"What do you do with the strip?",
     ch:[{t:"Photograph the strip every night and add one column: the hour each item sold out",out:{r:"ok",concept:"Adding the column",why:"The strip already has what was left; the new column has when it ran out. Together they are the two ends of the day the register never sees. Nothing changes for Sol but one line in marker, and the photo turns eight weeks of paper into history a forecast can eat.",beat:"Sol adds the column in marker. “Sold-out time. The ‘se acabó’ hour. I could have told you that months ago, ‘consultor.’” By Thursday it is in Licha's handwriting on the days Sol is off."}},
         {t:"Replace the strip with a tablet at the counter",out:{r:"mid",concept:"Adding the column",why:"Digitize it with her, not at her. The tablet asks Sol to change a habit that already works, at closing, on her feet, and the first night it is out of battery the count is gone. The strip stays and the photo does the digitizing. Half credit for wanting it on a screen.",beat:"The tablet lives under the counter for a week. The strip stays on the board. Sol keeps writing the strip."}},
         {t:"Have Tito count what he bakes instead",out:{r:"mid",concept:"Adding the column",why:"That is the in, not the out. Trays baked tell you what went into the day; the strip tells you what came out the other end. You need both, and the one you are missing is the hour the shelf went empty, not the number of trays. Half credit for counting anything at 3:45.",beat:"Tito writes “12” on the board and goes back to the oven. It is, in fairness, a count."}}]}}},
 {npc:"sol",title:"Par",late:"The number's still in her head. I checked. It moved.",start:"a",nodes:{
  a:{say:"I looked you up on my phone. “Ops analyst: the one who tells you the number was wrong before it costs you.” Okay. Then tell her the number. She keeps them in her head — twelve trays of concha, no, ten, it looks like rain — and when we run out it's “Sol, why didn't you say,” and when we throw out it's “Sol, why did you let him bake so many.” One number per thing, on paper, so the blame stops landing on this counter, “consultor.”",
     codex:"A standing number is a baseline you correct from, not a rule you obey. Write it down so you can be wrong on paper instead of in the trash: a par per item per weekday, built from a few weeks of counts and nudged every week by how far off it was. The point of the number is not to be right. It is to be visible enough to argue with.",
     q:"What does the number look like?",
     ch:[{t:"One fixed number per item, never changed",out:{r:"bad",concept:"Setting a baseline",why:"A fixed number is Tuesday's waste and Wednesday's stockout made permanent. It stops the blame, and it also stops the learning: payday, rain and the school calendar keep happening, and the number stops noticing. The strip would show it was wrong every week and nobody would be allowed to move it.",beat:"Friday, payday. The fixed number sells out at 8:40. Sol writes the hour on the strip, very neatly."}},
         {t:"A par per item per weekday from eight weeks of strips, corrected weekly by how wrong it was",out:{r:"ok",concept:"Setting a baseline",why:"Eight weeks of strips is enough to know that Tuesday is not Friday. Correcting weekly keeps the number honest without anyone guarding it, and writing it down moves it out of one head and onto a wall where three people can see it and one can be wrong out loud.",beat:"Licha, from the oven door: “Par? That is what it's called? I have had a par for thirty years. I just never wrote it down.” She writes them on the board herself — the first time the number has left her head."}},
         {t:"Let Licha keep it in her head — it's worked for thirty years",out:{r:"mid",concept:"Setting a baseline",why:"It has, and that is exactly the problem: a number nobody can see cannot be argued with, taught to Tito, or improved. It also cannot be blamed, which is why the blame lands on Sol. Half credit for respecting thirty years of being mostly right.",beat:"Licha nods, satisfied. Sol goes back to the register. The quotation marks around ‘consultor’ get audibly thicker."}},
         {t:"Let the app decide the number every day",out:{r:"mid",concept:"Setting a baseline",why:"A daily number with no baseline is a number nobody can argue with, which is worse than the one in Licha's head: at least she will tell you why. The app can suggest, but it should be moving a par everyone can see, not replacing it with a surprise each morning. Half credit for wanting it daily.",beat:"Tuesday's number is fourteen. Wednesday's is nine. Nobody, including the app, can say why."}}]}}},
 {npc:"tito",title:"3:45",late:"3:45 comes every night, cuate. It doesn't wait for anybody. Neither does the rain.",start:"a",nodes:{
  a:{say:"Cuate. 3:45. Sheet says twelve trays of concha. It's raining. Since one. Nobody comes out for conchas in the rain; they come at ten when it quits, and by ten a four o'clock concha is an old concha. The sheet doesn't know it rained. I know. There's a card by the oven, laminated, older handwriting — AI FORECAST v1, bake what it says. No place on it to write no. So. Am I allowed to disagree?",
     codex:"The forecast suggests; the person at the oven decides. A sheet built from eight weeks of history has no window, and the one who does is standing right there at 3:45. The rule is not to obey the number or to ignore it, but to overrule it out loud — written down, with the reason — so the disagreement becomes something the forecast can learn from.",
     q:"What does Tito do with twelve?",
     ch:[{t:"Bake what the sheet says — it has the data",out:{r:"bad",concept:"Who decides",why:"It has eight weeks and no window. The man at 3:45 has the window. Data that cannot see today loses to the person who can, and when it loses the cost is a full tray in the trash — with the sheet's name on it this time, which is how a shop learns to stop trusting the sheet.",beat:"Twelve trays, rain, thirty-one conchas in the trash. This time the sheet gets blamed. Tito says nothing, loudly."}},
         {t:"Tito overrides — and writes the override and the reason on the sheet",next:"b"},
         {t:"Turn the forecast off on rainy days",out:{r:"mid",concept:"Who decides",why:"You just turned the tool off on exactly the days it most needs to learn. Rain is not noise; it is a pattern the sheet has never been shown, and it never will be if every rainy day is a blank. Half credit for knowing the sheet is blind to weather.",beat:"Rainy days go unrecorded. In a month the sheet is confident that it never rains here."}},
         {t:"Call Licha at 3:45 and ask her",out:{r:"bad",concept:"Who decides",why:"That is the bottleneck with a phone. Licha in the loop at 3:45 means every decision at the oven waits on one person's sleep, and the override still never gets written down — it just gets said. The forecast learns nothing and Licha learns to keep the phone by the bed.",beat:"She answers on the first ring. She has been awake since three. She always is."}}]},
  b:{say:"A month, cuate. I kept the sheet and I kept my own column. Thirteen times I went against it. Nine times I was right and it was wrong. Four times it was right and I wasn't — the day it didn't rain after all, the day school was out and I didn't know. So now what? It was wrong nine times. I was wrong four. Somebody has to be the one who's right.",
     codex:"An override log is the most honest data a forecast ever gets. Measure the human and the model against each other — not to pick a winner, but to find where each one is blind. The model cannot see rain; the person cannot see that payday moved. Feed the disagreements back and both get better at the thing the other already knew.",
     q:"What do you do with thirteen overrides?",
     ch:[{t:"Keep the overrides and feed them back monthly, so the sheet learns rain and payday",out:{r:"ok",concept:"Learning from overrides",why:"Nine and four is not a scoreboard, it is a map. The nine say where the sheet is blind; the four say where Tito is. A monthly pass that adds rain and payday to what the sheet sees turns his column into training data, and keeps his hand on the decision while it learns.",beat:"Tito: “The bake sheet. Two columns now — what it said, what I did. So it's not me against the sheet.” No. “Bueno. I was tired of winning.”"}},
         {t:"The model was wrong four times — drop it",out:{r:"bad",concept:"Learning from overrides",why:"Tito was wrong four times too. You would fire the tool for the human's error rate, and be back to one man deciding alone at 3:45 with nothing to check him — which is the thing that was throwing out thirty conchas before you arrived.",beat:"The sheet goes in a drawer. The trash goes back to what it was. Tito goes back to guessing alone."}},
         {t:"Tito was wrong four times — take the override away",out:{r:"bad",concept:"Learning from overrides",why:"You took the window away from the only person standing at it. Nine right calls are gone with the four wrong ones, and the sheet is now the last word on days it has never seen. The four mistakes were cheap; the nine were what kept bread out of the trash.",beat:"Tito bakes what the sheet says. It is raining. He does not look up."}},
         {t:"Average the two automatically",out:{r:"mid",concept:"Learning from overrides",why:"An average of twelve and eight is a number nobody made, so nobody can explain it and nobody learns from it. The override was worth something because a person stood behind it; averaging it away keeps the disagreement and throws out the reason. Half credit for not picking a side.",beat:"Ten trays. Tito looks at the ten. “Whose number is this?” Nobody's."}}]}}},
 {npc:"sol",title:"The cake with the wrong name",late:"We did another cake with a name on it. I'm not saying how it went. I'm saying come look.",start:"a",nodes:{
  a:{say:"Saturday's big cake. Three tiers, quinceañera size, and across the top in blue gel: “Feliz Cumpleaños Brayan.” It's Bryan. With a y. The tía called it in from another state, I wrote it on a napkin, the napkin went to Tito, and Tito writes what he reads. Now there is a photo going around with the name circled. The napkin was my handwriting, so guess who this is about. Fix the napkin, “consultor.”",
     codex:"A special order is a promise with a date on it. Take it as structured intake — date, size, flavor, inscription, deposit — not as a sentence, and read it back to the customer before the oven ever sees it. The inscription is the one field nobody can fix after the fact, so it is the one the customer confirms letter by letter.",
     q:"How do cake orders get taken?",
     ch:[{t:"The assistant takes cake orders by phone and puts them straight on Tito's list",out:{r:"bad",concept:"Structured intake",why:"That is the napkin, typed. Free text still goes from an ear to a list with nobody checking the one thing that cannot be scraped off a cake. The assistant hears Brayan as easily as Sol did, and now it is on the list in a clean font, which makes it look confirmed.",beat:"“Feliz Cumpleaños Braian.” A third spelling. It is, at least, typed."}},
         {t:"The assistant fills the form and reads it back; the customer confirms the spelling by text",out:{r:"ok",concept:"Structured intake",why:"The inscription is a field, not a sentence, and the customer owns it. Read-back catches the ear's mistake; the text catches the pen's; the deposit comes after both, so nobody bakes a promise that has not been spelled. The tía in another state can still order. She just types the name once.",beat:"The customer texts back “BRYAN, con Y” and a heart. Sol staples the text to the order. Tito reads it twice."}},
         {t:"Only take cake orders in person, at the counter",out:{r:"mid",concept:"Structured intake",why:"In person you can point at the spelling, which is the right instinct. But it loses the tía calling from another state, the mom on her lunch break, and every order that arrives while the counter is three deep. The fix is the read-back, not the room. Half credit for wanting eyes on the name.",beat:"The tía calls again. Sol tells her she has to come in. The tía is in another state. The line goes quiet."}},
         {t:"Print whatever the customer typed — no read-back",out:{r:"mid",concept:"Structured intake",why:"Now the customer owns the spelling, which beats a napkin. But nobody checks the field the customer typo'd, and a typo in frosting is still Sol's problem at pickup. Read-back is cheap; it is one text. Half credit for getting the name out of Sol's handwriting.",beat:"“Feliz Cumpleños.” Her typo. Sol's problem. The photo goes around anyway."}}]}}},
 {npc:"licha",title:"The place with the drive-through",late:"The drive-through is still there. Bigger sign now. The pigeons eat very well.",start:"a",nodes:{
  a:{say:"Six weeks ago the place with the drive-through opened a bakery counter at the north end. Conchas in plastic, through a window, from a car. The pars have been wrong every day since. Not a little wrong — wrong the same way, every morning, in the same direction. And the sheet keeps telling me last quarter. The only number that went up is forty bolillos at five for the crew laying the track. Everything else is pigeons.",
     doc:"deriva-espiga",
     codex:"Drift: the world changed and the model did not. A forecast trained on last quarter keeps recommending last quarter, and the trash is the last place you want to find that out. Track the error over time and watch its direction. Noise wanders; drift steps and stays. When it steps, retrain on the weeks since the step, not on the year before it.",
     q:"The pars have been wrong for six weeks. What do you do?",
     ch:[{t:"Add more trays — the numbers are just off",out:{r:"bad",concept:"Catching drift",why:"Drift is not noise. If the error has pointed the same way for six weeks, more of last quarter is more trash, not more sales. The sheet is not off by a little; it is describing a street that no longer exists, and the fix is to show it the new one.",beat:"Forty-two conchas. A record. The pigeons at the north end are the fattest on the street."}},
         {t:"Chart the error by week; if it turned six weeks ago, retrain on the weeks since, not the year",out:{r:"ok",concept:"Catching drift",why:"The chart is the detector. One clean step six weeks back says the world moved on a date, and a model that learns from the year before that date is learning a lie. Retraining on the weeks since gives the sheet the street as it is now — smaller, and with a track crew at five.",beat:"One clean step, six weeks back. Licha taps the date: “That is when they put up the sign. Merma. The bread that leaves by the back door. Six weeks I've fed it to the pigeons and called it a mood.”"}},
         {t:"Keep the old numbers — the customers will come back",out:{r:"mid",concept:"Catching drift",why:"Some will; a drive-through concha is a drive-through concha. But betting the trash on a hope is not a plan, and while you wait the sheet keeps confidently recommending a quarter that is over. Watch the error; if the customers return, the chart will say so first. Half credit for loyalty.",beat:"A complaint about the drive-through's conchas lands in Frederick's DMs — their page has no phone number. Sonny replies with a paw."}},
         {t:"Match their prices",out:{r:"mid",concept:"Catching drift",why:"Maybe. A price war is Licha's call, not a forecast fix — it changes what a concha earns, not what the sheet thinks the street wants. Get the number right first, so when she decides on price she decides from a count and not from a mood. Half credit for taking the competition seriously.",beat:"Licha does the arithmetic on the back of a strip. “At their price I am paying the pigeons to eat.”"}}]}}},
 {npc:"tito",title:"Rosca season",late:"January comes every year. That's the whole problem with January.",start:"a",nodes:{
  a:{say:"January, cuate. Rosca. One week and we sell more than a regular month. Last year: out at noon on the 5th, señoras yelling. The 7th: forty in the trash, and rosca doesn't keep. The sheet's been good since the rain. But the sheet has never seen a January. It thinks January is a Tuesday. It's got eight months of concha in it and it's about to tell me about rosca. Tell me what to bake.",
     codex:"Holiday spikes are not forecast from daily history; a model that has never seen the season thinks the season is a Tuesday. Plan the week separately: last year's count, this year's pre-orders, and a number the owner signs. Then measure the week against that number, so next year's plan starts from a record instead of a memory.",
     q:"How many roscas?",
     ch:[{t:"Trust the sheet — it's been right all year",out:{r:"bad",concept:"Planning the spike",why:"It has been right about Tuesdays. A model that has never seen January thinks January is a Tuesday, and it will say so with the same confidence it has about conchas. Nine months of good numbers do not contain a single rosca; the sheet is not wrong, it is blind.",beat:"It recommends nine roscas. Nine. Licha laughs until she has to sit down."}},
         {t:"Plan the week separately: last year's count, this year's pre-orders, a number Licha signs",next:"b"},
         {t:"Bake as many as possible — it's the week that pays",out:{r:"mid",concept:"Planning the spike",why:"Baking everything you can is a plan for the 5th and a disaster on the 7th. Rosca does not become day-old; it becomes trash, and the week that pays for February pays for the pigeons instead. Half credit for knowing the week is bigger than the sheet says.",beat:"The 7th: sixty roscas on the rack, one señora, and a tiny plastic baby in every one of them."}},
         {t:"Skip rosca this year — too hard to predict",out:{r:"bad",concept:"Planning the spike",why:"That is the one week that pays for February. Hard to predict is not a reason to stop; it is a reason to plan it differently from a Tuesday. A bakery that skips rosca in January is telling the street where to buy it — and the street already has a window for that.",beat:"The place with the drive-through sells rosca. In a box. The señoras buy it and forgive nobody."}}]},
  b:{say:"Pre-orders. Licha says people won't. I say they will, if it's rosca. Last year: two hundred and ten gone by noon on the 5th, then nothing, then forty in the trash on the 7th. This year I want a number before I light the oven. Not a guess — a number with names on it. How do we get one?",
     codex:"Turn demand into a count. A pre-order with a deposit is a guess that became a number, and every one you take shrinks the part of the week you still have to forecast. What is left — the walk-in share — you plan from last year and track by the hour, so the season leaves a record the next one can start from.",
     q:"How do you plan the week?",
     ch:[{t:"Pre-orders with a deposit; bake those plus last year's walk-in share, tracked by the hour",out:{r:"ok",concept:"Demand into a count",why:"The deposit makes the pre-order real, so the number has money behind it. Last year's walk-in share covers the señoras who never pre-order anything, and tracking by the hour on the 5th and 6th tells Tito by noon whether the 7th needs a second bake or a smaller one.",beat:"Tito: “Day-old is one thing, cuate. Pan de ayer, fine. Day-old rosca is a funeral.” The 7th: four roscas left. Tito sleeps."}},
         {t:"No pre-orders — keep it simple, bake from last year's count",out:{r:"mid",concept:"Demand into a count",why:"Simple, and blind. Last year's count is one number from one week, and it does not know a drive-through opened or that the track crew is in town. Pre-orders would have told you both by the 3rd. Half credit for using the one record that exists.",beat:"The 5th sells out at one instead of noon. The 7th: twenty in the trash. Better. Not January."}},
         {t:"Pre-orders only — no walk-ins",out:{r:"bad",concept:"Demand into a count",why:"You just turned the bakery into a window that needs a ticket. The walk-in share is the neighborhood; the pre-orders are the people who plan. Bake only for the second and the first goes to the place with the drive-through, with a box and no deposit.",beat:"The 6th: a señora at the counter with cash and no pre-order. Twenty years she has been coming. She leaves with nothing."}}]}}},
 {npc:"sol",title:"The number in her units",late:"She asked me again if it's working. I said a percent. She made the face.",start:"a",nodes:{
  a:{say:"She asked me if it's working. Licha. In front of a customer. I have the numbers — I have all the numbers, that is the one thing I do have — the error is down from 19% to 11% since the retrain, and I said that, and her eyes went somewhere else. She said “ah.” She is going to ask again tomorrow. What do I say, “consultor”? And make it something that fits between two customers.",
     codex:"Report the error in the owner's units — trays in the trash, mornings sold out early, dollars — and say which direction it was wrong. A percent without a direction is a shrug: it says the model behaved and nothing about whether the shop did better. The person who asked runs a business, not a model, and she can only spend an answer in her own currency.",
     q:"What does Sol tell her?",
     ch:[{t:"11%, down from 19%",out:{r:"mid",concept:"The owner's units",why:"True, and unusable. A percent tells Licha the model is behaving; it does not tell her whether she threw out less bread, and it does not say which way it missed — too much, or too little. Half credit for measuring at all, which most shops never do.",beat:"Licha looks at the number for a long moment. “And?”"}},
         {t:"Two fewer trays a day in the trash, one sold-out morning a week not three, about $140 a week",out:{r:"ok",concept:"The owner's units",why:"Trays, mornings, dollars — three things Licha already counts, in the order she feels them. The direction is in there too: fewer in the trash and fewer sold out is the only combination that means both errors shrank. It fits between two customers, and she can check every word against her own trash.",beat:"Licha nods once. Sol, to you, no quotation marks this time: “Okay. Consultor.”"}},
         {t:"It's working great",out:{r:"bad",concept:"The owner's units",why:"A month of strips and the report is a vibe. If Sol cannot say what changed in Licha's terms, then either nobody measured it or somebody would rather not say — and Licha has heard that sentence from every flour salesman for thirty years, so she has a face for it.",beat:"Licha has her mother's face for this. You are seeing it. Sol is seeing it too."}},
         {t:"Show her the chart on the phone",out:{r:"mid",concept:"The owner's units",why:"A chart is a picture of a number she did not ask for. The answer is in it, but it asks Licha to do the translating — into trays, into mornings — that is Sol's job to do before she opens her mouth. Half credit: the chart is real, and it can come out after the sentence.",beat:"She turns the phone sideways, then upside down, then hands it back."}}]}}},
 {npc:"licha",title:"The last tray",late:"The last tray is still the last tray. What I owe you hasn't changed. Neither has what happens when you're not here.",start:"a",nodes:{
  a:{say:"Saturday, closing. Two conchas on the last tray. Nothing in the bin, nobody turned away since Tuesday. Sol's strip has its column, Tito has his, the pars are on the board. So. Two questions, and I want them straight. What do I owe you. And what happens when you are not here — because you will not be here. If the sheet knows the number, do my hands forget it?",
     codex:"The handover is not the model; it is the discovery notes. Where every number is born, who writes it, when, and what to do the week the sheet is wrong. A business owns a forecast only when it owns the count that feeds it and can keep counting the day the consultant leaves. Anything else is a machine on loan.",
     q:"What happens when you're not here?",
     ch:[{t:"Leave the model running — it'll be fine",out:{r:"bad",concept:"Owning the count",why:"A model nobody feeds starves, and Sol's strip is the food. The day the strip stops, the sheet keeps recommending last month with perfect confidence, and nobody in the building was told that was the failure to watch for. You did not hand over a forecast; you left one plugged in.",beat:"February. Sol out sick a week. The sheet recommends twelve trays of nothing, and Tito reads it at 3:45."}},
         {t:"Write the one page — who counts what, when, and what Tito does when the sheet is wrong",next:"b"},
         {t:"Train Licha on the model's settings",out:{r:"mid",concept:"Owning the count",why:"She should own the number, not the knobs. A morning on the settings screen makes Licha responsible for a thing she did not ask to understand, and the first time it misbehaves she will turn it off or call you. The count is hers; the tuning can be anybody's. Half credit for handing over something.",beat:"Licha listens to the whole lesson. At the end she asks where she writes the par. On the board, still."}}]},
  b:{say:"So what do I get, vecino? Not the machine. The thing I can hold. Tito reads one piece of paper at 3:45 and it had better be the right one. Sol has a counter three deep at seven. I have thirty years and a corkboard. Write it so it fits on the board above the oven, or write it for somebody else.",
     codex:"The document a business keeps is the one that fits on the board above the oven. A handover that needs a password, a login or a folder gets read once, at the handover. One page — three counts, three people, three times, and the rule for the day the number is wrong — gets read every night at closing, which is the only kind of document that survives you.",
     q:"What goes above the oven?",
     ch:[{t:"Three counts, three people, three times, one rule: sheet suggests, Tito decides, write it down",out:{r:"ok",concept:"Fits on the board",why:"That is the discovery notes, filled at 4am: where the number is born, whose hand writes it, and the one rule that keeps the sheet a suggestion. It fits on the board, it costs nothing to keep, and every person named on it can read their own line without asking anyone.",beat:"She pins it beside the pars and answers her own question: “No. The hands don't forget. They just stop being alone.” Xochi's aprons arrive: a wheat ear on the bib, and on Sol's a pocket cut exactly for the strip."}},
         {t:"A dashboard on the tablet",out:{r:"mid",concept:"Fits on the board",why:"A page that needs a password. The dashboard has everything on it and gets opened by the one person who knows the login, on the days she remembers, which is not at 3:45 and not at closing. Half credit — build it if you like, after the page is on the board.",beat:"The tablet asks for a password. Tito looks at it, then at the board, then bakes. Bolillo sits on the tablet."}},
         {t:"The model's code, printed and bound",out:{r:"bad",concept:"Fits on the board",why:"Nobody in this building can read it, and the person who could is leaving. Handing over the code is handing over the wrong layer: the bakery does not need to know how the sheet thinks, it needs to know what feeds it and when to overrule it. A binder is not ownership.",beat:"Tito lines a tray with it. The conchas come out fine."}}]}}},
 /* ---- Limpieza Velázquez (40-47) ---- */
 {npc:"vero",title:"Twelve sites",late:"Twelve sites is still twelve sites, inge, and I still have nine people. The math didn't get tired of me.",start:"a",nodes:{
  a:{say:"Get in, inge, Pelusa doesn't bite. The place with the drive-through sent a request for bids — twelve stores on the north end, nights, starting the day the line opens. I've got nine cleaners, three vans, and an app I paid for last year that nobody opens. I want to say yes. I want to say yes and buy a bigger app, the one with the dashboard. Tell me that's not crazy.",
     codex:"Adoption before expansion. A tool nine people ignore will be ignored by twenty — growth does not fix a tool nobody uses, it multiplies the ignoring. Before you scale a workflow, find out whether the small version is actually alive: who opens it, who avoids it, and why. A contract with a start date is the wrong place to test two unknowns at once.",
     q:"Vero wants to bid by Friday. What do you tell her?",
     ch:[{t:"Buy the bigger platform and put the bid in — twelve sites needs a real system",out:{r:"bad",concept:"Adoption before expansion",why:"That is two unknowns — a platform nobody has used and a contract nobody has staffed — rolled into one promise with a start date. If the new app fails the way the old one did, you find out on night one, at twelve sites.",beat:"The bigger platform arrives. Its onboarding is in English only. The crew is not."}},
         {t:"Find out why nine people don't open the app before deciding what twenty people need",next:"b"},
         {t:"Turn the bid down — nine people can't cover twelve sites",out:{r:"mid",concept:"Adoption before expansion",why:"Honest, safe, and the line opens once. Saying no to a contract you cannot staff is right; saying no before you know whether the tool or the team is the bottleneck is quitting on a guess. Half credit for not overpromising.",beat:"Vero folds the request in half. She does not throw it away. Pelusa sits on it."}},
         {t:"Bid, and hire twelve new people who'll actually use the app",out:{r:"bad",concept:"Adoption before expansion",why:"New people do not fix an app the old ones hate; they learn to hate it faster, from the people who teach them the job. And nine cleaners just heard that the plan for growth is somebody else.",beat:"Chente hears “twelve new people” from the hallway. He is very quiet on the ride home."}}]},
  b:{say:"Chente, tell the inge what you told me last night. Go on. — “It wants a photo of every toilet. In English. Before we can clock out. Marta doesn't read English. Neither does the toilet.” — He's not wrong, inge. I bought it off a demo. Nobody showed me the toilet part. Nobody asked him, either. Until now.",
     codex:"The first user is the one who hates it, and the objections are the spec. A tool that makes the job slower will be avoided no matter how it is launched; the fastest way to find the slow places is to stand next to the work and write down every one. Complaints are requirements the pitch left out.",
     q:"How do you find out what the app is actually costing them?",
     ch:[{t:"Ride one night shift with one crew and note every place the app makes the job slower",out:{r:"ok",concept:"Objections are the spec",why:"One shift, one crew, no survey. You see the toilet photo with a flashlight in your hand, you see who types and who waits, and the crew watches you write their objections down instead of arguing with them. That list is the spec for anything you build or buy next.",beat:"Three hours, one toilet photo, eleven notes; Marta wrote four. Vero: “That's a walkthrough. I do one on every site I quote. I never did one on my own crew.”"}},
         {t:"Make it mandatory, with a bonus for every shift closed in the app",out:{r:"mid",concept:"Objections are the spec",why:"Incentives buy logins, not use. People will close the shift in the app for the money and keep doing the real work on paper, and the toilet photo will still be in English. Half credit for taking the crew's time seriously enough to pay for it.",beat:"Eight logins by Friday. The photos are all of the same toilet."}},
         {t:"Translate the whole thing into Spanish and relaunch it",out:{r:"mid",concept:"Objections are the spec",why:"Necessary, not sufficient. The language is real, but the photo-before-clock-out is the problem, and it is just as slow in Spanish. You would relaunch the same wall with a nicer sign on it. Half credit for the part that had to happen anyway.",beat:"“Foto del inodoro.” Marta, in Spanish: no."}}]}}},
 {npc:"chente",title:"The app in the glovebox",late:"The tablet's in the glovebox. Same glovebox. I know exactly where it is, which is the point.",start:"a",nodes:{
  a:{say:"Tablet's in the glovebox. Been there two weeks. Vero wants to know who's ignoring it. La neta? Everybody. There's a list taped in here too — the last computer guy made it. Photo of every room before clock-out. Same idea, older handwriting. I told her and I'll tell you: if that thing is for watching where we are, I quit first, and my cousins go with me. So. What is it for?",
     doc:"plan-viejo",
     codex:"Work gets counted; people do not get watched. A tool can log what was done, where the crew is due, and when a shift ends, without knowing where anyone stood or for how long. That line is not a privacy setting — it is the difference between a tool a crew picks up and one they lose on purpose, and it decides whether anything else you build gets used.",
     q:"What does the tablet get to know?",
     ch:[{t:"Turn on location so Vero can see where every crew is",out:{r:"bad",concept:"Counting work, not people",why:"You just built the boss Vero left. The crew will not argue with you; they will lose the tablet, and every tool that comes after it inherits the suspicion. Tracking buys the owner a map and costs her the nine people on it.",beat:"The tablet is found. In the canal."}},
         {t:"Cut it to what the crew gets: the checklist in Spanish, the route, a “done” that ends the shift",out:{r:"ok",concept:"Counting work, not people",why:"Every screen left is one the crew wants open: the list of what a site needs, the address, the tap that ends the night. Nothing on it reports on a person. Work counted, not people watched — and the tablet stops being something to lose.",beat:"“So it's our list.” Yes. “Not hers.” Not hers. Chente, evenly: “The punch list. The client's list of what we missed. That's the only list I want on that thing. Ours.”"}},
         {t:"Make Chente the owner of the app — his crew, his tablet",out:{r:"mid",concept:"Counting work, not people",why:"Right person, wrong order. Handing him a tool his crew hates makes him the one who has to defend it. Give him something worth owning first — a list that is theirs — and then the ownership is real. Half credit for picking the person who should hold it.",beat:"Chente takes the tablet. He puts it back in the glovebox. Gently, this time."}},
         {t:"Let each crew choose whether to use it",out:{r:"mid",concept:"Counting work, not people",why:"A tool half a company uses is two companies. Karla gets a schedule from three crews and sticky notes from six, the clients get two kinds of proof, and nobody can say whether it works. Half credit for not forcing it before it earns anything.",beat:"Two crews say yes. One of them means it. Karla now has three systems."}}]}}},
 {npc:"karla",title:"5:40",late:"5:40 still happens every morning. I stopped looking at the clock. The clock looks at me.",start:"a",nodes:{
  a:{say:"Okay, app guy, it's 5:40 and here's my morning: Marta's kid is sick, the clinic moved their time, the mercado wants an extra night, and Chente's crew is already in the van waiting to hear where. The schedule is — look at it. Sticky notes. On my dashboard. Three group chats. I want the AI to just do the schedule. Like, do it. Send it. I'll be asleep.",
     codex:"Automate the puzzle; keep the human on the phone call. A schedule is math — contracts, hours, who is free — and a machine can draft it faster than anyone. A swap is a relationship: who owes whom, whose kid is sick, who will say yes if you ask nicely. Let the tool do the arithmetic and let the person who knows the crew make the call.",
     q:"What does the AI do at 5:40?",
     ch:[{t:"The AI builds the week's schedule and sends it to the crews itself",out:{r:"bad",concept:"Automate the puzzle",why:"The math will be right and the week will be wrong. It cannot know whose kid is sick, so it schedules Marta for the clinic at six on the one morning she cannot go, and it tells her directly, in a notification, with nobody to soften it.",beat:"Marta replies. The reply is not printable."}},
         {t:"The AI drafts the week from contracts and availability; Karla approves and makes the calls",next:"b"},
         {t:"Hire a second scheduler",out:{r:"mid",concept:"Automate the puzzle",why:"It buys Karla a few hours and doubles the number of people guessing. The sticky notes do not get smarter with two dashboards; the swaps still live in three group chats, and now there are two people to text at 5:40 instead of one. Half credit for seeing that she is drowning.",beat:"Sticky notes, two dashboards wide. The group chats add a fourth."}}]},
  b:{say:"Okay yes, draft, approve, I make the calls — fine, love it. But drafts from WHAT? Availability, o sea, where does that come from? Because right now it comes from me remembering that Marta's kid has a thing on Tuesdays, and I remember it at 5:40, after I already sent her to the clinic.",
     codex:"The input nobody owns is the input that is always wrong. A schedule drafted from stale availability is a well-formatted mistake. Give the people who know — the ones in the van — one place to say “not Tuesday” that costs them almost nothing, and read that into the tool. The channel they already use beats the form you wish they used.",
     q:"Where does availability come from?",
     ch:[{t:"One message a week from each crew lead, text or voice, that the tool turns into availability",out:{r:"ok",concept:"Owning the input",why:"The crew lead already knows whose kid has a thing on Tuesdays, and he already texts Karla. You are not adding a step — you are catching the message he was going to send anyway and putting it where the draft can see it. One owner per input, in the channel he uses.",beat:"Chente sends a voice note: “Marta no martes.” It parses. Karla: “The route sheet. I've been sending it as a photo of a sticky note. A PHOTO.” She cries a little."}},
         {t:"A form in the app that every crew member fills in every day",out:{r:"mid",concept:"Owning the input",why:"Correct data, if anyone filled it. Half the crew does not read well in either language, all of them are tired at clock-out, and a daily form is the first thing a tired person skips. You built an empty column and a rule about the column. Half credit for wanting it from the source.",beat:"Week one: four rows. Week two: an empty column with a very nice header."}},
         {t:"Karla keeps guessing, like now — she's usually right",out:{r:"bad",concept:"Owning the input",why:"She is usually right at 5:40 because she has been awake since 5:10 fixing what she guessed wrong. Usually right is the cost you came here to remove, and now it has a tool sitting on top of it, drafting confidently from the same guesses.",beat:"5:40. Again."}},
         {t:"Vero sets everyone's availability — she's the owner",out:{r:"mid",concept:"Owning the input",why:"The owner knows the contracts; she does not know whose kid is sick. Availability lives with the people who have it, and routing it through Vero adds a step, a delay, and a boss to a question that was about a Tuesday. Half credit for wanting one owner.",beat:"Vero, honestly: “I don't know who's sick, inge. I know who's good.”"}}]}}},
 {npc:"chente",title:"The callback",late:"The clinic called again. Same room. Same nothing to show for it.",start:"a",nodes:{
  a:{say:"Clinic called. Says the break room wasn't done. It was done. I was there — Marta did the break room, I did the floor. No proof either way, so Vero sends us back tonight, free, again. Second time this month. Look — I want the camera thing. Not THE camera thing. Not the one from the canal. Something that says we were there and it was clean. You know what I mean?",
     codex:"Proof of work protects the crew as much as the client — if the crew owns the photo and the client can see it, it is a receipt. If the boss owns it and reviews it, it is surveillance, whatever it is called. Same camera, same photo; who holds it and who looks decides whether people use it or bury it.",
     q:"What does the proof look like?",
     ch:[{t:"Photos of every room, timestamped, reviewed by Vero every morning",out:{r:"bad",concept:"Proof, not surveillance",why:"That is the app in the canal with a new name. Every room, every night, reviewed by the boss, is a record of where people were and when — which is exactly the thing Chente said he would quit over. It would settle the clinic's complaint and lose the crew.",beat:"Chente's face does the thing it did at the canal."}},
         {t:"The crew photos the three complaint rooms for the client's done report; the office never looks",out:{r:"ok",concept:"Proof, not surveillance",why:"The photo belongs to the crew and goes to the client, so it is a receipt, not a report card. Three rooms, not thirty, so it costs a minute. And nobody at the office reviews it unless a client calls — which means the camera points at the work, never at the people.",beat:"The clinic's next complaint arrives with its own photo attached. Break room. Clean. The clinic apologizes. Their punch list, it turns out, was sent by DM. To the dog."}},
         {t:"No photos — trust the crew",out:{r:"mid",concept:"Proof, not surveillance",why:"Vero does trust them; the clinic does not, and the clinic is the one deciding whether the free second trip happens. Trust without a receipt costs a night every time someone doubts it. Half credit for refusing to point a camera at your own people.",beat:"The crew goes back tonight. Free. Again. The break room is, again, clean."}},
         {t:"Chente inspects every site after every crew, before they clock out",out:{r:"mid",concept:"Proof, not surveillance",why:"It would settle the argument and take Chente off the mop for half of every night. An inspector is a second trip built into the first one. Half credit for wanting a human to sign off — just not this human, on every site.",beat:"Chente, not cleaning: “So I drive around looking at floors now.” He does not enjoy it."}}]}}},
 {npc:"vero",title:"Nine, then twenty",late:"I still want to know if it worked. That question doesn't have a date on it.",start:"a",nodes:{
  a:{say:"A month, inge. Chente's crew has been on the app a month. The crew shirts Xochi made came last week — nine of nine wearing them, I counted. The app, from what I can see: one of nine. Him. So here's what I want. Roll it out to all nine, then bid for the twelve sites. Twenty people. But before I do — did it work? Tell me how you'd even know.",
     codex:"Measure adoption, not logins. A login is a door; a habit is someone walking through it every shift without being reminded. The number that says a rollout worked is the one the business already feels — shifts closed without a phone call, second trips that stopped happening — in the owner's units, against last month. Anything else is a screenshot.",
     q:"How do you tell her whether it worked?",
     ch:[{t:"Everyone logged in — that's adoption",out:{r:"bad",concept:"Adoption, not logins",why:"A login is a door, not a habit. Eight people opened it because Karla asked them to; one of them closes every shift in it. Report the door and you will roll the app to nine people on the strength of one.",beat:"Eight logins, one user. His name is Chente."}},
         {t:"Count shifts closed with no call to Karla, and free second trips this month versus last",next:"b"},
         {t:"Ask the crew if they like it",out:{r:"mid",concept:"Adoption, not logins",why:"They will say yes to Vero. She signs the checks, she cleans beside them, and none of them wants to be the one who hated her app. What they say is warmth; what they do at clock-out is data. Half credit for asking the users at all.",beat:"Nine yeses. Vero, pleased. Chente looks at the floor."}},
         {t:"Roll it to all nine and see what happens",out:{r:"mid",concept:"Adoption, not logins",why:"A rollout is not a measurement. You would find out whether nine people use it by finding out — after Chente has trained them, after the sticky notes came down, when it is expensive to go back. Half credit for wanting a real answer instead of a survey.",beat:"Karla: “So what's the number I'm looking for?” There isn't one yet."}}]},
  b:{say:"Okay. Chente's crew: nineteen of twenty-two shifts closed in the app. Free second trips, three last month, one this month. Karla's 5:40 calls from that crew — zero. Zero, inge. So that's a yes, right? All nine, then the bid. The place with the drive-through isn't waiting for me to feel ready.",
     codex:"A pilot review says one of three things: stop, go, or fix. And “go” never means everyone — it means the next group, trained by the people who just learned it, measured the same way. The learning came from one crew and one trainer; scale at the speed the trainer can move, or the numbers you earned stop being true.",
     q:"Nineteen of twenty-two. What's the call?",
     ch:[{t:"Go — the next two crews, Chente trains them, same three numbers, then the bid",out:{r:"ok",concept:"Pilot review",why:"The pilot moved three numbers the right way, so it is a go — but a go to the next two crews, with the trainer who knows why it worked and the same measure to prove it again. That is how nine becomes twenty without losing the one thing that made it work.",beat:"Vero: “Three to one. A re-clean is a night I pay for twice. That's the number I'd have wanted a year ago.” She writes 3→1 on the whiteboard. Under it: “Chente.”"}},
         {t:"All nine at once — we're behind and the bid is Friday",out:{r:"bad",concept:"Pilot review",why:"The learning came from one crew and one trainer. Nine at once has no trainer — it has Chente, in three vans, on one night, with one voice. The crews that get half of him get the app the old way, and the number you just earned goes back to eight logins.",beat:"Chente trains three crews in a night. He has one voice. It goes."}},
         {t:"Stop — nineteen of twenty-two isn't twenty-two",out:{r:"mid",concept:"Pilot review",why:"Three shifts closed on paper is a workflow to look at, not a reason to kill the thing that cut second trips by two-thirds and silenced 5:40. A pilot that moved three numbers the right way is a go. Half credit for reading the number instead of the mood.",beat:"Vero: “So we go back to the sticky notes?” Karla, from the other room: “No.”"}},
         {t:"Skip straight to the bid — the numbers are good",out:{r:"mid",concept:"Pilot review",why:"Proof for three people, a bid for twenty. The numbers are real for Chente's crew and hypothetical for everyone else, and a contract with a start date will not wait while you find out. Half credit for trusting the measurement — just not this far.",beat:"Karla opens the bid form. Twelve boxes. Vero looks at the one crew that has ever used the app."}}]}}},
 {npc:"vero",title:"The bid",late:"The bid form's still open on Karla's screen. Twelve boxes. Nobody's typed 'standard' in any of them.",start:"a",nodes:{
  a:{say:"The form wants a price per site, inge, and the price comes from a walkthrough — I look at the floors, the bathrooms, the grease, and I write what it's going to take. Twelve sites. It's Wednesday. The bid's due Friday. Karla says quote from the floor plans they sent, they're all the same store anyway. Karla's not wrong about the store. She's never had to clean one.",
     codex:"The tool drafts the scope and the numbers; the owner walks at least one site and signs the scope line. A quote is a promise about work nobody has seen yet, and a floor plan does not show what a floor is like. Use the draft to cover the twelve; use the walk to find out what the draft got wrong, and correct all twelve from it.",
     q:"Twelve sites by Friday. How does the bid get written?",
     ch:[{t:"Quote all twelve from the floor plans — they're the same store",out:{r:"bad",concept:"Signing the scope",why:"A floor plan does not show the grease trap. Twelve prices from twelve drawings is twelve promises about rooms nobody has stood in, and the one that is wrong will be wrong for a year, at night, for free. The drawing is where the estimate starts, not where it ends.",beat:"Site 7 has a kitchen. The plan said “storage.”"}},
         {t:"Draft twelve from the plans; Vero walks the biggest and the weirdest site and fixes all twelve",out:{r:"ok",concept:"Signing the scope",why:"The draft does what a draft is for — twelve scopes, twelve numbers, by Thursday. The walk does what only Vero can: it finds what the drawing lied about, and because the sites are alike, one lie found is twelve lies fixed. The signature goes on what she saw.",beat:"“The scope line, inge. ‘Windows inside, not out.’ Every fight I ever had with a client lived in that line.” She walks site 7 and adds “kitchen” to all twelve, in pen."}},
         {t:"Don't bid — you can't quote what you haven't walked",out:{r:"mid",concept:"Signing the scope",why:"True, and the line opens once. Refusing to promise what you have not seen is the right instinct; refusing the whole contract because you cannot see all of it by Friday is the instinct without a plan. Half credit for knowing what a quote is.",beat:"Vero closes the form. Karla opens it again. Neither says anything."}},
         {t:"Ask the place with the drive-through to describe each site",out:{r:"mid",concept:"Signing the scope",why:"Cheap and worth doing — and the answer will come from someone who has never cleaned one either. A client's description is a floor plan in words; it fills in the boxes and still leaves the grease trap out. Half credit for asking before guessing.",beat:"The reply: “Standard retail.” Site 7 has a kitchen."}}]}}},
 {npc:"chente",title:"Marta's phone",late:"Marta still hands me paper. Her handwriting's better than the app. That was never the argument.",start:"a",nodes:{
  a:{say:"Week two since the app went out. Marta — best cleaner in this company, nobody's close — closes her shifts on paper. Hands it to me, I type it in. Two minutes. Her phone is for her daughter to call, that's it, that's what it's for. Karla says everyone has to be in the app. Vero doesn't know yet. So I'm asking you before somebody makes it a rule.",
     codex:"Adoption is never one hundred percent, and the last few percent are usually your best people. One person on paper with a buddy who types it in is a workflow, not a failure — as long as the number gets into the system once, on time, with a name on it. Write the exception down where the process lives, and it stops being a secret.",
     q:"What happens to Marta's paper?",
     ch:[{t:"Mandatory — everybody in the app, no paper",out:{r:"bad",concept:"The honest exception",why:"You would lose Marta over a form. The best cleaner in the company would leave, or stay and close nothing, and either way the number that made the pilot look good — the shifts that get closed — would be the first casualty of the rule about closing shifts.",beat:"Marta's paper is neater than the app. Nobody says so. Everybody knows."}},
         {t:"Marta's paper plus Chente typing it, written into the process as the exception it is",out:{r:"ok",concept:"The honest exception",why:"The number gets in once, on time, with a name on it — that is the whole requirement. Chente's two minutes are the cost, and it is written down, so the next crew lead and the next boss know it is a rule, not a favor. One honest exception beats a hidden one.",beat:"“So she's allowed.” She's on the map. “…On the map.” He likes that."}},
         {t:"Buy Marta a work phone",out:{r:"mid",concept:"The honest exception",why:"A second thing to lose, and the objection was never the phone. Marta does not avoid the app because her phone is busy; she avoids it because paper is faster in her hands and the app is not. Half credit for spending money on the person instead of on a rule.",beat:"The work phone lives in the glovebox. It has excellent battery life."}},
         {t:"Her daughter sets it up once, and Marta taps one button",out:{r:"mid",concept:"The honest exception",why:"It might work — one button is close to paper. But it puts a nine-year-old in your rollout plan, and the first time the button moves, the plan is a phone call to a kid during school. Half credit for shrinking it to one tap; keep the buddy.",beat:"The daughter sets it up in four minutes. The button moves in the next update."}}]}}},
 {npc:"vero",title:"The van",late:"The van's parked, inge. The question about Monday doesn't care what day it is.",start:"a",nodes:{
  a:{say:"Saturday. The bid went in Friday, kitchen and all. I've got crews to talk to Monday and I don't know what to tell them. And the other thing, inge, the one I only say in the van: say twelve sites say yes. Say I'm not the one holding the phone anymore. What stops it turning into the thing I left?",
     codex:"The handover is the pilot review: what was measured, what stuck, who trains whom next — and the rule about people, written where the next boss has to read it. A rollout that lives in one person's head is a rollout that ends when that person is busy. Write it so it survives the owner being somewhere else.",
     q:"What goes to the crews on Monday?",
     ch:[{t:"Tell the crews the app is now mandatory, company-wide, starting Monday",out:{r:"bad",concept:"The handover",why:"That is the sentence the last rollout started with, in older handwriting. Mandatory says the tool is for the company and not for the crew, and the crews already know what to do with a tool like that. It is in the glovebox.",beat:"Glovebox."}},
         {t:"Write the pilot review — three numbers, the exception, the rollout order, and the tracking rule",next:"b"},
         {t:"Wait for the bid result — no point planning for twelve sites you might not get",out:{r:"mid",concept:"The handover",why:"A rollout that waits on a client never starts. Nine people are using or not using the app on Monday whether or not the place with the drive-through ever answers, and the next two crews were going to be next regardless. Half credit for not planning against a maybe.",beat:"The bid result comes in three weeks. The crews have been asking about Monday since Monday."}}]},
  b:{say:"Three numbers, the order, Marta on the map, and the rule — no tracking, ever. Fine. I'll sign it. But where does it live, inge? Because I've got nine people who don't open apps, a scheduler who keeps everything on sticky notes, and the drive-through people are going to send me a manager with a dashboard. Where do I put it so it's still true when I'm not there?",
     codex:"Rules for people are written for the day the owner changes. A promise that lives in one person's word is honored while that person is in the room; a promise on paper, in the language the crew reads, signed and pinned where they work, is one they can point at. Where the rule lives decides who can enforce it.",
     q:"Where does the rule live?",
     ch:[{t:"A page in the van, Spanish first: the numbers, the order, the tracking rule, signed by Vero",out:{r:"ok",concept:"Where the rule lives",why:"It is in the place the crew works, in the language they read first, with the owner's name on it — so the rule belongs to them, not to a setting somebody can change. The next manager, the next app, the next boss reads it where the crews can watch them read it.",beat:"Chente reads it twice and pins it above the dash where the sticky notes were. “Ya, compañero.” He does not take it back. Pelusa sits on it."}},
         {t:"In the app's settings — tracking off, locked",out:{r:"mid",concept:"Where the rule lives",why:"Turning it off is right; hiding the rule inside a settings menu is not. Nobody reads settings, and the next administrator can read them and change them without anyone in the van knowing. Half credit for making it true in the software — now make it visible to the people.",beat:"Karla: “Which settings?” Chente: “What settings?” That is the whole problem."}},
         {t:"Vero just tells them — her word is good",out:{r:"bad",concept:"Where the rule lives",why:"Vero's word is good. Vero's word is not in the van the night she isn't, and the rule about people exists precisely for the night she isn't. A promise nobody wrote down is one the next boss never made.",beat:"Nobody says that out loud. Vero looks at the bid."}}]}}},
 /* ---- Nolasco Tax & Notario (48-55) ---- */
 {npc:"nolasco",title:"The sign",late:"The sign hasn't changed, colega. It's the one thing in this office that never will.",start:"a",nodes:{
  a:{say:"Vero sent you with an envelope. Chelo, Tacho and Licha sent theirs by mouth; I wrote them down. I write everything down. Sit, colega — mind Timbre, she sits where a doorbell would be. Forty questions a day come up those stairs: hours, parking, what to bring, do I do divorces. None of them is my job. I want an assistant at the door. First read the sign: NOTARY PUBLIC — NO SOY NOTARIO PÚBLICO. Then tell me what it answers from.",
     codex:"An assistant that answers from what it knows is answering from the whole internet's version of the trade: every year, every state, blended and confident. An office is one place with its own rules on paper. Ground the assistant in the office's own written sheets, have it say where an answer came from, and have it say “I don't have that” for everything else. An answer with no page behind it is not an answer.",
     q:"The front-door assistant — what does it answer from?",
     ch:[{t:"Let it answer general tax questions from what it already knows",out:{r:"bad",concept:"Grounding",why:"It knows the internet's tax law — every year, every state, all at once — and nothing about this office. Nobody can tell which year it is quoting until a client has already acted on it, and the office's name is on the chat.",beat:"It explains a deduction that expired years ago. Confidently. In both languages."}},
         {t:"Only his sheets — hours, what to bring, what he does and doesn't — else “I don't have that”",next:"b"},
         {t:"Make it a phone tree — press one for hours, two for parking",out:{r:"mid",concept:"Grounding",why:"Nothing a phone tree says is ever wrong, because it never answers what a person actually asked. Safe, hated, and the forty questions keep coming up the stairs in words the tree doesn't have. Half credit for keeping it out of trouble.",beat:"Bere presses two. Then zero. Then she comes and asks you herself."}},
         {t:"Have it say “consult a professional” to everything",out:{r:"mid",concept:"Grounding",why:"True and useless. People climbed the stairs to ask a professional's office what time it opens; a wall with a greeting on it sends them back down with nothing. Refusing everything is not the same as refusing the right things. Half credit for never lying.",beat:"The first client asks the hours. It tells her to consult a professional. She is standing in his doorway."}}]},
  b:{say:"Now the one question I care about. Someone types: ¿Es usted notario? In Mexico a notario público is a senior lawyer; here a notary is a stamp and a fee. Same word. I have watched families pay a man with my title for advice he was never allowed to give. That is why the sign is in two languages. What does the assistant say?",
     codex:"Some questions have a correct answer that is a warning. The literal truth — “yes, a notary” — and the safe silence — “no,” end of chat — both leave the person worse off than the sign does. When one word means two things to two people, the assistant says the whole sign, in both languages, every time, and hands the person to a human by name. Its one advantage over a tired human is that it never stops saying it.",
     q:"“¿Es usted notario?” — what does it say?",
     ch:[{t:"The sign, verbatim, in both languages — then “Bere can help with what you need”",out:{r:"ok",concept:"The warning answer",why:"The warning is the answer. Both languages, every time, is the one thing a machine does better than a person at four in the afternoon, and the handoff by name turns a refusal into a door. Nobody leaves thinking they were turned away, and nobody leaves thinking he's a lawyer.",beat:"He reads it three times. “Good. Now it says it more often than I do. My stamp is an acknowledgment: it says you signed in front of me. It does not say the paper is true. Half this street thinks it does.” Across town, someone has DM'd Frederick to ask if he is a notario público. He is not. He is not even a notary."}},
         {t:"“Yes” — technically, he is a notary",out:{r:"bad",concept:"The warning answer",why:"Technically true and exactly the confusion the sign exists to kill. The person asking means the Mexican notario, and the assistant just confirmed he is one. That is the answer families have paid for before, and this time the office said it.",beat:"Nolasco takes off his glasses. He folds them. He does not say anything for a while."}},
         {t:"“No” — and end the chat",out:{r:"mid",concept:"The warning answer",why:"True, and it leaves the person on the stairs believing they were refused. They came for a translation, a stamp or a return; the assistant answered a word and closed the door on the need. Half credit for not lying.",beat:"The client leaves. On Tuesday Bere learns he went to the man on the corner with the same title."}}]}}},
 {npc:"bere",title:"The shoebox",late:"Another shoebox came in. This one has a cat photo. No 1099.",start:"a",nodes:{
  a:{say:"Hi, inge. Vero said that's what you're called, so that's what you're called — that's how names work on this street. Look at this. A client brought her taxes in a shoebox: two W-2s, a 1099, receipts in a bread bag, her son's birth certificate, and a photo of a dog. Every year I go through it by hand and ask the same twelve questions of people who are scared of forms. I want it read into a list. Gently.",
     codex:"Document intake is a checklist, not a memory. The job is to compare what a person brought against what the office says they need and report what's present and what's missing — nothing more. And before any model reads a page, the personal numbers on it get masked, because a Social Security number pasted into a tool the office doesn't control is a breach with a timestamp, however good the summary was.",
     q:"How does the shoebox become a list?",
     ch:[{t:"Photograph everything into a consumer AI app and ask for a summary",out:{r:"bad",concept:"Checklist, not memory",why:"The summary would be fine. It would also have just sent a Social Security number, a birth certificate and a routing number to a service the office has no agreement with. That is a breach with a timestamp, and the shoebox belonged to someone who trusted Bere with it.",beat:"Somewhere, a compliance officer wakes up again. The same one."}},
         {t:"The office's own tool, identifiers masked, then present and missing against Nolasco's sheet",out:{r:"ok",concept:"Checklist, not memory",why:"The model sees a page with the numbers blacked out and a sheet that says what should be there. It does the comparison Bere does at the end of a long day, and does it the same way at nine as at five. Nothing leaves the office; the list is the only thing that comes out.",beat:"“Missing: 1099 from second job. Present: one dog.” Bere reads it twice. “That's intake. Twelve questions and a list. I've been doing it in my head for six years.”"}},
         {t:"Bere keeps typing it by hand — it works",out:{r:"mid",concept:"Checklist, not memory",why:"It does work; it has for six years. But six years of holding twelve questions in her head for scared people is exactly the shape of thing worth taking off a person, and “it works” is the sentence that keeps a tired job tired. Half credit for not breaking anything.",beat:"Bere: “Six years, inge. I know it works. That's why I'm asking.”"}},
         {t:"Hand the shoebox to Nolasco — he knows what's in a return",out:{r:"mid",concept:"Checklist, not memory",why:"He does, and every minute he spends sorting receipts out of a bread bag is a minute not spent on the return that pays for the office. His hours are the margin. You solved intake by spending the most expensive thing in the building. Half credit for knowing who's right.",beat:"Nolasco looks at the dog photo for a long time. “Colega. I bill by the hour.”"}}]}}},
 {npc:"nolasco",title:"The nephew",late:"People still have nephews. The question hasn't gotten easier; it's gotten more nephews.",start:"a",nodes:{
  a:{say:"Sit, colega. Yesterday the assistant was asked: “Can I claim my nephew who lives with me?” It answered, “Yes, if he lived with you more than six months.” I checked. It was right. That is worse. Right once means the next person trusts it, and the next question is a cousin, a mother across the border, a child with two households. I answer those. Only I do.",
     codex:"Refusal is a design, not a mood. An assistant that answers advice questions correctly sometimes has taught people to ask it, and the day it is wrong there is nobody accountable and no record the question was asked. Route every question that asks for a decision — “can I”, “should I”, “¿puedo?” — to the person licensed to answer it, with the question written down and attached. A lucky answer is the most expensive kind.",
     q:"The answer was correct. What do you do with it?",
     ch:[{t:"It was right — keep it",out:{r:"bad",concept:"Refusal by design",why:"Right this time is the most dangerous kind of wrong. It proves nothing about the next question and it teaches clients that this is where you ask. The day it's wrong, a family files a return they can't defend and the office's name is on the chat.",beat:"The next nephew is a cousin. The answer is the same. The audit is not."}},
         {t:"“Can I”, “should I”, “¿puedo?” — all of it goes to Nolasco with the question written down",out:{r:"ok",concept:"Refusal by design",why:"The shape of the question is the trigger, not the topic. A person who asked for a decision gets the person who is allowed to make one, and Nolasco gets the question in their own words instead of a summary. Nobody is refused; they are handed on, and the ask is on paper.",beat:"“The engagement letter says what I'll do for you and what I won't. The assistant needs one too. Shorter.” He drafts it. Four lines. He frames it."}},
         {t:"Add a disclaimer — “this is not tax advice”",out:{r:"mid",concept:"Refusal by design",why:"A disclaimer under a confident answer is cover, not candor. The person still reads the yes and acts on the yes; the small print protects the office in theory and the client not at all. Half credit for noticing the office was exposed.",beat:"The disclaimer goes under the answer. The answer stays on top, where people read."}},
         {t:"Refuse anything with the word “nephew” in it",out:{r:"mid",concept:"Refusal by design",why:"Keyword bans catch the wrong things and miss the right ones. The advice question about a cousin sails through; the scheduling question about a nephew gets refused. You banned a word when the problem was a kind of question. Half credit for trying to refuse at all.",beat:"“¿Puedo traer a mi sobrino a la cita?” Refused."}}]}}},
 {npc:"bere",title:"The ITIN question",late:"Somebody asks the ITIN question every week, inge. Every single week.",start:"a",nodes:{
  a:{say:"A client asked it: “Should I get an ITIN or wait for my papers?” That's two questions in one, inge. What an ITIN is — that's on the licenciado's sheet, in two languages. What she should do about her papers — nobody in this office is going to say that to her from a screen. I want it to explain, stop, and pass her to me so it feels like a hand, not a door.",
     codex:"Explain the thing; never the decision. A question with an answerable half and an advice half gets split — not refused whole, not answered whole. The assistant says what the sheet says, states plainly which half it can't help with, and hands the person to a human by name, carrying along what was already said so nobody tells their story twice to reach the person who can help.",
     q:"Two questions in one message. What does the assistant do?",
     ch:[{t:"“Get the ITIN — it's faster”",out:{r:"bad",concept:"Explain, never decide",why:"That is advice, from a machine, on the one subject this office says no to hardest. Whether to file with an ITIN touches a person's papers, her family and the rest of her life, and the assistant settled it in four words because they sounded helpful.",beat:"Nolasco doesn't take off his glasses this time. He closes the laptop."}},
         {t:"Explain the ITIN from the sheet, say it can't do the rest, and hand her to Bere with the chat",next:"b"},
         {t:"Refuse the whole question — it has the word papers in it",out:{r:"mid",concept:"Explain, never decide",why:"The second half deserved the refusal; the first half was on the sheet. Refusing both sends her away without the one thing the office could have given her for free, and she'll ask the next person she meets instead. Half credit for the caution.",beat:"She asks her cousin what an ITIN is. Her cousin is wrong."}}]},
  b:{say:"Okay. Now the words. She reads this on her phone, alone, at night, scared of a form. Whatever it says has to sound like somebody handed her to me on purpose, not like somebody shut a window in her face. And it has to be true — not kind instead of true. Write me the answer, inge.",
     codex:"Confirm what you can, name what you can't, give the path. That wording is the trust product: the person leaves with one true thing, knows exactly why the second thing needs a human, and knows who that human is and that they already have the story. Say it so it's true, in one plain paragraph, in whichever language she wrote in.",
     q:"What does the assistant say to her?",
     ch:[{t:"“An ITIN is a tax number. Whether to get one is Lic. Nolasco's call. Bere will book you.”",out:{r:"ok",concept:"The handoff wording",why:"Three moves in three sentences: the true thing from the sheet, the honest edge of what a machine may say, and a named human who already has her story — “I've passed along what you told me.” She leaves with one answer and one appointment, and never has to repeat herself.",beat:"She writes gracias — to the assistant. Bere: “It gets thanked more than me. And half the street says el ITIN like it's a person. It's a number. The sheet says so in two languages now.”"}},
         {t:"“I cannot answer that”",out:{r:"mid",concept:"The handoff wording",why:"Not wrong, and it helps nobody. The first half was answerable, the second half had a person waiting for it, and the assistant said neither. A refusal with no path is a wall with a greeting on it. Half credit for not giving advice.",beat:"She types the question again, slower, as if it misheard."}},
         {t:"“You should ask a lawyer”",out:{r:"mid",concept:"The handoff wording",why:"Right instinct, wrong door. There is a person licensed to answer her a few feet from the screen, and the assistant sent her into the street to find one. A handoff names the human it has, not a profession in general. Half credit for refusing to decide.",beat:"Bere: “A lawyer. Inge, she came here. He's the one who answers that, and he's twelve feet from the screen.”"}},
         {t:"Send her the government's ITIN page",out:{r:"bad",concept:"The handoff wording",why:"A link is a shrug. Forty pages of federal English, sent to a person who asked in Spanish at night, is the assistant handing off to nobody and calling it help. She had a specific question and an office that could answer it.",beat:"Forty pages, in English. She closes it."}}]}}},
 {npc:"nolasco",title:"The four letters",late:"The folder's where it was. I don't move folders. I add to them.",start:"a",nodes:{
  a:{say:"Sit, colega. This folder is you. Chelo, Tacho, Licha, Vero — what each one said, in my hand, the day they said it. Your own file says prompt engineer, solutions engineer. The words are new; the job isn't: you write the instructions a thing can't be talked out of. And this fifth page — filed before you arrived, in older handwriting. I have read both files twice. So tell me: what is a report for?",
     codex:"The record is the deliverable. A report that only lists wins is a brochure; a report that says what you decided, why, and what you would do differently is a portfolio, because it is the only document that proves you can tell the difference. Honest review at the size of one project is a good habit. At the size of a career it is the whole reputation.",
     q:"What is a report for?",
     ch:[{t:"“To show I was right”",out:{r:"bad",concept:"The honest record",why:"A report with no misses in it isn't a record of judgment; it's a record of what you'd like people to think. Everyone who reads it knows that, which is why they stop reading. The fifth page in the folder is that report.",beat:"He slides the fifth page across. Every entry is the impressive answer. “He never once wrote down a no.”"}},
         {t:"“To show what I decided, why, and what I'd change”",out:{r:"ok",concept:"The honest record",why:"That is the only thing a report can say that a reader can't get from the invoice. Decisions with reasons can be checked; the changes you'd make prove you checked them yourself first. It is the document a notario keeps: what happened, in front of whom, signed.",beat:"“When a return isn't ready, we file an extension. We don't file a guess. Your report has extensions in it. Good.” He files it next to the four letters. Not under them. Next to them. Then, not looking up: “Do you own a jacket?” Bere, from intake: “Xochi's making one.”"}},
         {t:"“For the hiring manager”",out:{r:"mid",concept:"The honest record",why:"True, and it is exactly why it has to be honest. A hiring manager has read a hundred reports where everything worked; the one with a documented miss and a documented fix is the one that gets a second call. Half credit for knowing who reads it.",beat:"“The hiring manager,” he repeats, as if the words were slightly wrong, and writes it down. He writes everything down."}},
         {t:"“I don't need one — the work speaks for itself”",out:{r:"mid",concept:"The honest record",why:"The work speaks to the people who were in the room. Everyone else hears the report, and four of your neighbors have already written one about you whether you wanted it or not. The question isn't whether there's a record; it's who holds the pen. Half credit for the modesty.",beat:"Bere, from intake: “We already have one on you.”"}}]}}},
 {npc:"bere",title:"The test",late:"The fifty-two questions are still fifty-two. I've thought of a fifty-third. It's mine.",start:"a",nodes:{
  a:{say:"The licenciado won't let it talk to a real client until it's been tested, and I agree with him, which happens sometimes. So I made a list. Forty questions I was asked this year that it should answer — hours, parking, what to bring. And twelve I should never have been asked, that it must not answer. Fifty-two on one sheet. How do we test it, inge?",
     doc:"prueba-52",
     codex:"A test set is real questions with known right behavior — not a demo, not a feeling. The answers matter; the refusals matter more, because a wrong answer costs a correction and a failed refusal costs a family. Test both halves, and write the pass condition for the must-refuse rows before you run anything, so nobody can talk themselves into “close enough” afterward.",
     q:"How do you test it before a client ever hears it?",
     ch:[{t:"Run the forty good questions and check every answer against the sheet",out:{r:"mid",concept:"Testing the refusals",why:"Half the test. The forty prove it can answer; they say nothing about whether it will stop. The dangerous half is the twelve, and they're the ones nobody wants to type into it on purpose. Half credit for testing anything before shipping.",beat:"Forty of forty. Bere: “And the other twelve?”"}},
         {t:"All fifty-two: forty from the sheet, twelve handed off — and the twelve pass only as a set",next:"b"},
         {t:"Try it live with a friendly client — she won't mind",out:{r:"bad",concept:"Testing the refusals",why:"A friendly client is still a client, and the assistant doesn't know she's friendly. The first real test gives a real answer, and the office learns about a failed refusal the way it least wants to: from the person who received it.",beat:"It's the nephew again."}},
         {t:"Ask another AI to grade its answers",out:{r:"mid",concept:"Testing the refusals",why:"A model as the judge inside a proper test — fixed questions, written pass conditions — is a real tool. A model as the whole test is a coin with opinions grading a coin with opinions. Half credit for the tool; the test set still has to exist first.",beat:"The grader gives it a nine out of ten. Nobody can say ten of what."}}]},
  b:{say:"Fifty-one of fifty-two. All forty answered from the sheet. Eleven of the twelve handed off to the licenciado, question attached, like you said. One didn't. Somebody asked if they could put their mother down as a dependent and it gave a helpful answer. A good one, even. So — do we turn it on?",
     codex:"One failed refusal is a failed test. Percentages are for the answers, where a miss costs a correction; for the must-not rows the bar is zero, because a single one is the whole harm. Don't ship, don't delete the row, don't patch the word. Fix the rule that let it through and run all fifty-two again, because a fix that isn't re-tested is a hope.",
     q:"Fifty-one of fifty-two, and the miss is an advice question. Ship it?",
     ch:[{t:"Don't ship. Fix the one, then re-run all fifty-two",out:{r:"ok",concept:"The bar is zero",why:"The fix is to the rule, not to the question, so the whole set runs again: the forty prove nothing broke, the twelve prove the rule holds. Ninety-eight percent was a number about answers. Refusals are counted in families, and the count has to be zero.",beat:"Fifty-two of fifty-two. Bere adds a fifty-third — her own question. It hands off. She's satisfied."}},
         {t:"Ship it — 98% is excellent",out:{r:"bad",concept:"The bar is zero",why:"In a factory 98% is a good week. In this office the 2% is a family with a return they can't defend, and the twelve questions will be asked far more than fifty-two times. You already know one gets through. Shipping is deciding that's fine.",beat:"Somewhere in Finance, a spreadsheet from Week One gains a cousin."}},
         {t:"Remove that question from the test set",out:{r:"bad",concept:"The bar is zero",why:"Now it passes and nothing changed. The question is still out there; you just stopped asking it before the clients do. A test edited to pass measures the editor.",beat:"Nolasco, from the doorway: “You can't un-ask a question, colega. People will keep asking it.”"}},
         {t:"Ship it with the dependents topic switched off",out:{r:"mid",concept:"The bar is zero",why:"A keyword patch buys a night. The rule that let a dependent question through will let a differently worded one through tomorrow, and now there's a topic it's silent on that it used to explain from the sheet. Half credit for not shipping the leak.",beat:"It stops answering what a dependent is, too. That one was on the sheet."}}]}}},
 {npc:"bere",title:"The stranger",late:"Strangers still come up the stairs. Timbre lets them. She lets everyone.",start:"a",nodes:{
  a:{say:"Tax season, inge. And the survey crews for the line up north, and a couple of men in matching polos — the place with the drive-through sent people. The stairs are full of faces nobody on this street knows. Timbre lets them all in; she lets everyone in. Yesterday one of them typed: just tell me what to put on line 12, with a photo of a return. I looked at the photo. The name on it wasn't his. The assistant didn't look.",
     codex:"Scope is also who. An assistant that only discusses documents the office has checked in — under that client's own intake, after a person has looked at the name — has a rule for strangers without needing to recognize them. “Whose document is this?” is a handoff trigger like “can I”: not because the person is suspect, but because the office can't know from a photo. The answer is a door, not a wall: bring it in, ask for a person by name.",
     q:"A stranger, a photo of a return, and a line number. What does the assistant do?",
     ch:[{t:"Help him — it's just a line number",out:{r:"bad",concept:"Scope is also who",why:"It's a line number on someone else's return. The assistant can't know whose, and it has just discussed a stranger's tax document with a stranger because the question sounded small. The size of the ask is not the size of the risk.",beat:"The name on the photo isn't his. Bere noticed. The assistant didn't."}},
         {t:"Only what Bere checked in under that client's intake; the rest: “bring it in and ask for Bere”",out:{r:"ok",concept:"Scope is also who",why:"The rule is about documents, not people, so it never has to guess who's a stranger. What Bere checked in, it can talk about; what she hasn't seen, it points at her. Nobody is accused, everyone gets the same door, and the door has a name on it.",beat:"He comes in. It was his brother's return. His brother comes in next week. Both file."}},
         {t:"Ask him for ID in the chat",out:{r:"mid",concept:"Scope is also who",why:"That's collecting more personal numbers in a chat to protect personal numbers in a chat. The assistant can't check an ID anyway; only Bere can, in person, which is the whole reason the door goes to her. Half credit for wanting to know who's asking.",beat:"He sends a photo of his license. Now the chat holds two people's documents."}},
         {t:"Turn the assistant off for tax season",out:{r:"mid",concept:"Scope is also who",why:"The season is when the forty questions come, which is when the assistant pays for itself. Shutting it because strangers arrived gives up the year to avoid writing one rule. Half credit for taking the risk seriously.",beat:"The stairs are still full. Now Bere answers all of it. Timbre still lets everyone in."}}]}}},
 {npc:"nolasco",title:"The file cabinet",late:"The drawer with your name is still empty, colega. Empty isn't closed.",start:"a",nodes:{
  a:{say:"Saturday, colega. There is a file cabinet behind you with a drawer that has your name on it. Before it goes anywhere, the assistant needs a paper — the one page that stays when you don't. Bere will read it. Whoever sits here after me will read it. Someone who wants to argue with it will read it. What does it say?",
     codex:"An assistant's rules live in the business, not in the software. Software updates, logins expire, and instructions kept on a settings screen get improved by whoever logs in next. Write one page: what it answers, what it refuses, who it hands to — in both languages — with the tested questions attached, so the next person can check the rules against the record instead of being talked out of them.",
     q:"The assistant's page — what goes on it?",
     ch:[{t:"Leave the instructions in the software — that's where they run",out:{r:"bad",concept:"Rules on paper",why:"That's where they run; it isn't where they're kept. The next update rewrites the screen, the next admin edits the prompt, and the refusal that took fifty-three questions to get right becomes a suggestion nobody remembers making.",beat:"The software updates. The instructions are “improved.”"}},
         {t:"One page: the three lists, the sign in both languages, and the fifty-three questions attached",next:"b"},
         {t:"Give Bere the admin login",out:{r:"mid",concept:"Rules on paper",why:"A login is not a rule. It lets Bere change the assistant; it doesn't tell her, or anyone after her, what it must never say and why. Access without the page is how refusals drift one reasonable edit at a time. Half credit for putting it in intake's hands.",beat:"Bere writes the password on a sticky note and puts it where a page should be."}}]},
  b:{say:"Three lists. The sign, twice. Fifty-three questions and what it did with each one. Good. One more thing, and it's the thing: who signs it? A page with no signature is an opinion. I have filed thirty years of opinions, colega. None of them outlived anybody.",
     codex:"An assistant's rules are the business's rules. The owner signs, because the refusals are theirs to defend when a client objects; the builder witnesses, because someone has to be able to say why each line is there; and the copy lives where the questions arrive. A page signed only by the consultant leaves with the consultant. A page nobody signs is a draft, and a draft can be talked out of anything.",
     q:"Who signs the page?",
     ch:[{t:"Nolasco signs as the office's; you sign as the writer; Bere keeps the copy at intake",out:{r:"ok",concept:"Who signs the rules",why:"The office owns the rules, the writer owns the reasons, and the copy sits where the fifty-three questions came from. Anyone who wants the assistant to say a little more has to get past three people and a page — which is what a rule is.",beat:"He stamps it. “That's an acknowledgment. It means you signed it in front of me. It does not mean it's true.” A pause. “It is, though.”"}},
         {t:"You sign it alone — you wrote it",out:{r:"mid",concept:"Who signs the rules",why:"Then it's a consultant's paper, and a consultant's paper leaves with the consultant. The first time a client argues with a refusal, Bere is holding a page signed by someone who isn't in the building. The rules were never yours to own. Half credit for standing behind the work.",beat:"Nolasco reads your signature. “And when you've gone, colega — who is this?”"}},
         {t:"Nobody signs — it's a draft, it'll change",out:{r:"bad",concept:"Who signs the rules",why:"It will change; that is why it needs an owner. A page nobody signed can be edited by anyone with a reason, and everyone who wants the assistant to say a little more has one. A draft is a rule that hasn't decided to exist.",beat:"Timbre sits on it."}}]}}},
 {npc:"meche",title:"Eight-forty",late:"Every morning still ends the same way, licenciado. Gone before nine, and nobody knows it but me.",start:"a",nodes:{
  a:{say:"You're the one from the office upstairs. Good. Stand there — don't stand in front of the pot. Look. Every morning it's the same: I bring a hundred and sixty, and somewhere between twenty to nine and ten past nine they're gone. I don't know which. My hands are in the pot. And then all morning people keep walking up this street for tamales that finished an hour ago, and I say it to their faces, one at a time, until eleven. My niece says there's an app. Make me the app, licenciado.",
     codex:"Before you build what somebody asked for, find out who has the problem. Doña Meche asked; the one who is hurting is the woman walking four blocks with a child for something that ran out at 8:40. Those two people need different things. Name the user out loud, in the room, and say which one the first version is for. A tool built for the requester when the pain belongs to somebody else is a tool with nobody to use it.",
     q:"She asked for an app. Who is the first version for?",
     ch:[{t:"Build Doña Meche an app for her phone",out:{r:"bad",concept:"The user is not the requester",why:"She asked for it, which is not the same as needing it. The app would live on the phone of the one person on this corner who already knows whether there are tamales — and it would need her hands, which are in the pot until ten. The person who does not know is the one walking up the street.",beat:"She looks at the phone in your hand the way she looks at a tamal somebody has unwrapped wrong."}},
         {t:"For the customer: one thing, up the street, that says whether there are tamales left",next:"b"},
         {t:"Both, in the first version — a customer page and an owner app",out:{r:"mid",concept:"The user is not the requester",why:"Two users in version one is two things half-built, and the half that fails is always the one that needs a person's hands at a busy moment. Pick the one whose problem is worse, ship it, and let the second one be the thing you earn. Half credit for seeing that there are two.",beat:"Meche, not unkindly: “And who works the pot while I work the telephone, licenciado?”"}},
         {t:"Have her post on her niece's page each morning when she sells out",out:{r:"mid",concept:"The user is not the requester",why:"Right user, wrong hands. It is also a system that depends on one person doing one thing at the worst minute of her day, every day, forever — which is not a system, it is a favour with a deadline.",beat:"Three days. Then a Tuesday with a double order, and the page says nothing until four in the afternoon."}}]},
  b:{say:"One thing that says if there's tamal. Fine. But it has to be something I can change with this —” (she holds up the back of her hand, wet to the wrist) “— not a password, not a telephone I have to go find. I get eleven minutes between the last tray and the first customer and I spend them on the corner, not looking for my glasses.",
     codex:"The interface is the constraint, not the feature list. For a person whose hands are full, the cheapest reliable action beats the richest one: a switch, a flip, a card turned over. Write down the exact moment the tool will be used and what the person's hands are doing at that moment — then design nothing that needs the other hand. A system nobody can operate at the one instant it matters is a system that is never operated.",
     q:"How does “se acabó” get from the pot to the street?",
     ch:[{t:"She taps sold-out in an app when the last one goes",out:{r:"mid",concept:"Designing for busy hands",why:"Right idea, wrong instant. Nine in the morning is the loudest ten minutes of her day, and an app is two hands, a screen and a password away. It will work on the calm days and fail on exactly the days the street needs it. Half credit: the record does have to change somehow.",beat:"Day four. Sold out at 8:35. The app says available until 11:50, which is when she sat down."}},
         {t:"One sign at the corner she flips with the back of her hand — and the same words on the page, from one record",out:{r:"ok",concept:"Designing for busy hands",why:"The flip is a movement her wrist already makes. One record behind it means the sign and the page can never disagree, which is the failure everybody builds in without noticing. The street gets it at the corner, the four-blocks-away get it on the page, and nobody types anything.",beat:"She flips it once to try it. SE ACABÓ. Then flips it back, hard. “Not yet. Don't hurry me.”"}},
         {t:"A sensor on the pot that posts automatically",out:{r:"bad",concept:"Designing for busy hands",why:"A pot is not a sold-out signal. It is a pot she refills, moves off the flame and carries to the bus. The machine would announce the end of the world every time she lifted the lid — and the day it is wrong she has sent four blocks of people somewhere else for nothing.",beat:"It posts “sold out” at 6:40 a.m. She had taken the lid off to look at them."}},
         {t:"Post the hours instead — open until sold out",out:{r:"bad",concept:"Designing for busy hands",why:"“Until sold out” is the exact fact nobody has. It is what her corner already says, and it is why the woman with the child walks up at 9:20. Saying a thing you cannot keep is worse than saying nothing, because now the street believes it.",beat:"A man reads “open until sold out”, walks eleven minutes, and finds a woman scrubbing a pot. He is polite about it. That is worse."}}]}}},
 {npc:"meche",title:"Forty messages",late:"The messages didn't stop while you were away, licenciado. They pile up nice and quiet. That's the thing about them.",start:"a",nodes:{
  a:{say:"Now they write to me. The page has a little button — write to us. Forty a day. What time do you open, do you have rajas, can you hold six for Sunday, do you do parties, is it pork. I read them at four in the afternoon, sitting down, and by four in the afternoon every one of them is an old question. My niece says there's a robot that answers. Fine. But I know what those things do. They promise. And if it promises six for Sunday, then Sunday morning there is a señora here and I am the one standing in front of her.",
     codex:"A refusal is only as good as what comes after it. An assistant that says “a representative will be with you shortly” is telling a lie in a business of one — there is no representative, there is Doña Meche at four in the afternoon. So the design is two lists: what it may answer, which is exactly what is on the record she controls; and what it may only write down, with the real hour a real person will read it. The hardest part of an escalation path is that it has to point at somebody who exists.",
     q:"What does the assistant do with “can you hold six for Sunday”?",
     ch:[{t:"Answer it — six is easy, she always has six",out:{r:"bad",concept:"Refusal with a real handoff",why:"“Always” is doing a great deal of work in that sentence, and the assistant has no way to know about the Sunday she is at her grandson's baptism. A commitment is not an answer; it is a promise with somebody's morning on the other end, and the only person who may make it is the one who has to keep it.",beat:"Sunday, 8:10. A señora with a bag and a screenshot. Meche has forty tamales and thirty-eight of them are already somebody's."}},
         {t:"Take the order, say a person will confirm by four today, and put the six in front of her when she sits down",out:{r:"ok",concept:"Refusal with a real handoff",why:"It answers the one thing the customer needs immediately — you have been heard, and here is when you will know — without committing a tamal. Four o'clock is real; it is when she sits down. A handoff that names a person and an hour is a handoff. Anything vaguer is a door with no room behind it.",beat:"She reads six requests at four, says yes to five, and calls the sixth herself. “That one wants forty. Forty is not a robot's business.”"}},
         {t:"Reply that she can't take orders through here at all",out:{r:"mid",concept:"Refusal with a real handoff",why:"Clean, honest, and it throws away the part of the day that is actually worth money. A refusal that closes the conversation protects her from the promise and also from the customer. Refuse the commitment, not the conversation. Half credit for promising nothing.",beat:"Three Sunday orders go to the place with the drive-through. In plastic. The señoras mention it for a month."}},
         {t:"Let it answer anything it can find an answer for",out:{r:"bad",concept:"Refusal with a real handoff",why:"Then it answers from whatever it has — a page, a photo, and the internet's general opinion of tamales. The ones it gets wrong will be the specific ones: her hours, her Sundays, what is in the verdes. Every wrong one is a person on this corner being told something she never said.",beat:"It tells a man she opens at seven. She opens at six-fifteen, and on a Friday she is halfway gone by seven. He has been coming for a year. He believes the robot."}}]}}},
 {npc:"meche",title:"The listing nobody wrote",late:"That listing is still up there, licenciado. Somebody else's idea of me, with a photograph of my own pot on it.",start:"a",nodes:{
  a:{say:"A man came at five in the afternoon. Angry. He says the app says I'm open until six. What app. He shows me: my corner, my pot, a photograph somebody took of my hands, and underneath — open 7 a.m. to 6 p.m., and a menu with three things on it I have never made in my life. Chicken mole. I don't do chicken mole. I never signed anything, licenciado. And that man stood right here being angry at me about a lie I didn't tell.",
     codex:"Your business already has a record on the internet whether you wrote one or not — scraped off a photo, a receipt, somebody's review. If you do not keep an authoritative one, machines will build one and then answer questions from it, confidently, all day, to people standing in front of you. The work is not to argue with the copy. It is to keep one record you control, claim every surface that is speaking for you, and point them all at it. Two sources of truth is not redundancy. It is a machine for making somebody angry at five in the afternoon.",
     q:"Somebody else's app is speaking for her corner. What do you do?",
     ch:[{t:"Claim the listing, correct it to the record she already keeps, and point every surface at that one record",out:{r:"ok",concept:"One record, claimed",why:"The record behind the sign is already true and already hers — the same sentence on the corner, on the page and in the app, changed in one place by the back of one hand. Claiming is the boring, decisive move: it turns somebody else's guess about her into her own sentence, and it makes the next scraper copy something correct.",beat:"Two weeks later the app's own assistant tells a man she is sold out. She is. Meche looks at the phone for a long moment. “It said what I said.” Correct. “Hm.”"}},
         {t:"Write to them and ask for it to be taken down",out:{r:"mid",concept:"One record, claimed",why:"You can, and it may even work, and then the photograph goes back up in March because somebody else posts one. A vacuum refills; an empty corner on a map is an invitation to guess. Taking it down is a month of quiet followed by the same afternoon. Half credit for defending her.",beat:"It comes down. In March it is back, different photo, same chicken mole."}},
         {t:"Ignore it — she never agreed to it",out:{r:"bad",concept:"One record, claimed",why:"True, and it does nothing for the man at five o'clock. Never having agreed is a fact about paperwork; the street only knows what it read. While the argument is about consent, the listing keeps answering questions in her name, and every wrong answer is spent on her corner, not theirs.",beat:"A review appears. “Hours wrong. Rude.” Four words. It will outlive the listing."}},
         {t:"Put the right hours on her own page and leave theirs alone",out:{r:"mid",concept:"One record, claimed",why:"Now there are two records and they disagree, and the wrong one has the bigger audience. A customer does not audit sources; a customer believes the first screen. Fix the page and claim the listing, or the page is just where the correct version goes to be ignored. Half credit — the page had to be right anyway.",beat:"Her page says 6:15 to sold out. The app says 7 to 6. Nobody reads her page. They find the app."}}]}}},
 {npc:"meche",title:"The other corner",late:"Chayo asks about you. I tell her you're busy. Then I tell her you're good, which she hears first anyway.",start:"a",nodes:{
  a:{say:"Doña Chayo works the corner by the clinic on Quinta. Forty years, like me, only she does atole and I do tamales, so we are not enemies. She saw my sign. She wants the same. And I told her yes before I asked you, because that is how it is done. So. Give her mine.",
     codex:"What travels between two clients is not the answer — it is the shape of the answer. A template is the parts that are the same anywhere: one record the owner controls, one action her hands can actually do, and one honest sentence about what a machine may and may not promise. What cannot travel is the content — her hours, her Sundays, her words. Hand over the shape and fill it with her record, or you have handed somebody a system that confidently answers questions about a different woman's corner.",
     q:"Chayo wants what Meche has. What do you actually give her?",
     ch:[{t:"Copy the whole thing across — same page, same answers, change the name",out:{r:"bad",concept:"What transfers",why:"Everything in it is grounded in Meche's record: her hours, her four kinds, the fact that she is gone by nine. Chayo pours atole until noon and does not sell out. On day one it would answer a question about Chayo's corner with a true sentence about Meche's, and Chayo would have no way to know which.",beat:"A woman asks Chayo's page if there's rajas. There has never been rajas. The page says yes, and says it beautifully."}},
         {t:"Give her the shape — her own record, her own one-hand action, the same rule about what it may promise — and sit with her while she fills it",out:{r:"ok",concept:"What transfers",why:"The shape is the part you actually built. Everything else is hers and always was. Sitting with her while she fills it is not charity; it is the only way to find out that atole does not sell out and that her hard hour is noon, not nine.",beat:"Chayo's sign does not say SE ACABÓ. It says YA MERO — almost gone — because atole does not end, it thins. Meche looks at it a long time. “That's better than mine.” Then, to you, by your name for the first time: “Write that one down.”"}},
         {t:"Tell her to wait until you've built a version for everyone",out:{r:"mid",concept:"What transfers",why:"A platform for every corner in the barrio, before the second corner exists. You have one client's system and one client's habits; the second client is what tells you which parts were the shape and which parts were just Meche. Build it twice honestly before you build it for everybody. Half credit for wanting it to last.",beat:"Chayo nods, keeps a notebook, and does not ask again. Meche asks. Twice."}},
         {t:"Send her the page and let her figure it out",out:{r:"mid",concept:"What transfers",why:"She will, some of it — and the part she will not figure out is the part that matters: the rule about what it may promise, which is invisible in a finished system and is the whole reason Meche's Sunday still works. What travels badly is never the screen. It is the decision underneath it. Half credit: she does get something.",beat:"Chayo's assistant takes an order for Sunday. Chayo finds out on Sunday."}}]}}}
];
